  app.post('/api/public/fund-code/resolve', async (req, res) => {
    try {
      const inputCode = normalizeGiftCode(req.body?.code);
      if (!inputCode) return res.status(400).json({ error: "Enter a valid fund code." });

      const match = await findFundByGiftCode(inputCode);
      if (!match) return res.status(404).json({ error: "We couldn't find a fund with that code." });

      const fund = await storage.getFund(match.fundId);
      if (!fund) return res.status(404).json({ error: "Fund not found" });
      const ensuredFund = await ensureFundSlugAndPermanentEvent(fund, fund.userId);

      // Event code path
      if (match.eventId) {
        const event = await storage.getEvent(match.eventId);
        const childName = ensuredFund.recipientFirstName || "the fund";

        if (event && event.status === "active") {
          return res.json({
            code: match.code,
            codeType: "event",
            fund: { id: ensuredFund.id, name: ensuredFund.name, recipientFirstName: ensuredFund.recipientFirstName, slug: ensuredFund.slug },
            event: { id: event.id, name: event.name, slug: event.slug, status: event.status },
            redirectPath: `/${ensuredFund.slug}/${event.slug}`,
          });
        }

        // Event closed or missing — warm redirect to fund page
        return res.json({
          code: match.code,
          codeType: "event",
          eventClosed: true,
          eventName: event?.name || null,
          fund: { id: ensuredFund.id, name: ensuredFund.name, recipientFirstName: ensuredFund.recipientFirstName, slug: ensuredFund.slug },
          redirectPath: `/${ensuredFund.slug}`,
          warmMessage: event?.name
            ? `${event.name} has wrapped up, but you can still give to ${childName} directly.`
            : `That event has ended, but you can still give to ${childName} directly.`,
        });
      }

      // Fund code path
      const eventsForFund = await storage.getEventsByFund(ensuredFund.id);
      const permanentEvent = eventsForFund.find((event) => event.isPermanent);
      const availability = await buildPublicGiftingAvailability(ensuredFund, permanentEvent || null);

      res.json({
        code: match.code,
        codeType: "fund",
        fund: {
          id: ensuredFund.id,
          name: ensuredFund.name,
          recipientFirstName: ensuredFund.recipientFirstName,
          slug: ensuredFund.slug,
          status: ensuredFund.status,
        },
        availability,
        redirectPath: `/${ensuredFund.slug}`,
      });
    } catch (error) {
      console.error("Error resolving gift code:", error);
      res.status(500).json({ error: "Failed to resolve fund code" });
    }
  });

  app.post('/api/public/gift-invitations', async (req, res) => {
    try {
      const parentContact = String(req.body?.parentContact || "").trim();
      const childName = String(req.body?.childName || "").trim();
      const requesterName = String(req.body?.requesterName || "").trim();
      if (!parentContact) {
        return res.status(400).json({ error: "A parent email or phone is required." });
      }

      // Detect contact type. Email gets actual outreach. Anything else
      // (phone numbers, free text) gets the "we don't text yet, here's a
      // shareable link" path so the requester knows they need to deliver
      // it themselves. Previously the phone path was silently dropped
      // into a .jsonl file with no downstream action, and the success
      // toast politely lied about it.
      const isEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(parentContact);

      await fs.mkdir(path.dirname(GIFT_INVITATION_PATH), { recursive: true });
      await fs.appendFile(
        GIFT_INVITATION_PATH,
        JSON.stringify({
          parentContact,
          contactType: isEmail ? "email" : "phone_or_other",
          childName: childName || null,
          requesterName: requesterName || null,
          createdAt: new Date().toISOString(),
          source: "gift_lookup_page",
        }) + "\n",
        "utf8",
      );

      // Build attribution-tagged URL so when the parent clicks through
      // and signs up, the welcome experience and analytics can both
      // close the loop back to who asked them. ref + inviter params
      // match the same shape the gifter-loop emails use elsewhere
      // (see buildLoopStartFundUrl in gifterNotificationWorker.ts).
      const base = getAppBaseUrl(req);
      const params = new URLSearchParams({ ref: "gift-invitation-request" });
      if (requesterName) params.set("inviter", requesterName);
      if (childName) params.set("for", childName);
      const startUrl = `${base}/get-started?${params.toString()}`;

      let deliveryMode: "email" | "phone_no_outreach" = "phone_no_outreach";
      if (isEmail) {
        const delivery = await sendEmail({
          to: parentContact.toLowerCase(),
          subject: childName ? `Set up a Kiddo fund for ${childName}` : "Set up a Kiddo fund",
          text: [
            `Hi,`,
            "",
            requesterName
              ? `${requesterName} wants to gift ${childName || "a child you know"} through Kiddo.`
              : `Someone wants to gift ${childName || "a child you know"} through Kiddo.`,
            "Create a fund, share one link, and family can gift into a real investment account in under 60 seconds.",
            "",
            `Get started: ${startUrl}`,
            "",
            "The Kiddo team",
          ].join("\n"),
          tags: ["gift_invitation"],
          metadata: {
            childName: childName || null,
            requesterName: requesterName || null,
            source: "gift_lookup_page",
          },
        });
        deliveryMode = delivery.mode === "outbox_fallback" ? "phone_no_outreach" : "email";
      }

      res.json({
        success: true,
        deliveryMode,
        // Client uses this for the phone-path UI ("paste this in a text
        // to them"). Always returned so the client can render a
        // copy-to-clipboard fallback even on the email path if it wants.
        shareableUrl: startUrl,
        message:
          deliveryMode === "email"
            ? "Invitation sent. The parent can set up a fund and share it back when ready."
            : "We don't text yet. Send this link in a message and we'll guide them from there.",
      });
    } catch (error) {
      console.error("Error saving gift invitation:", error);
      res.status(500).json({ error: "Failed to save invitation request" });
    }
  });

  app.post('/api/gifter-notifications/opt-in', async (req, res) => {
    try {
      const sessionId = String(req.body?.sessionId || "").trim();
      if (!sessionId) return res.status(400).json({ error: "sessionId is required." });

      const session = await stripeService.getCheckoutSession(sessionId);
      const metadata: any = session.metadata || {};
      if (metadata.type !== "gift") {
        return res.status(400).json({ error: "Only gift checkouts can opt into updates." });
      }
      if (session.payment_status !== "paid") {
        return res.status(409).json({ error: "This gift has not finished processing yet." });
      }

      const paymentIntentId = typeof session.payment_intent === "string" ? session.payment_intent : session.payment_intent?.id;
      const gift = paymentIntentId ? await storage.getGiftByPaymentIntent(paymentIntentId) : undefined;
      const fundId = String(gift?.fundId || metadata.fundId || "").trim();
      if (!fundId) return res.status(404).json({ error: "Fund not found for this gift." });

      const fund = await storage.getFund(fundId);
      if (!fund) return res.status(404).json({ error: "Fund not found." });

      const email = String(req.body?.email || gift?.senderEmail || metadata.senderEmail || "").trim().toLowerCase();
      if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        return res.status(400).json({ error: "Enter a valid email address." });
      }

      const store = await loadGifterNotificationStore();
      const subscribers = store.subscribersByFund[fundId] || {};
      const existing = subscribers[email];
      // Anonymous flag rides through from the gift row. If the underlying
      // gift was sent anonymously, the subscriber record stores isAnonymous=true
      // even though we keep the email (we need it to send notifications).
      // The GET subscribers endpoint redacts email + name for these records
      // before returning to the parent. Per
      // feedback_anonymous_as_explicit_flag.md sub-rule.
      const giftIsAnonymous = Boolean((gift as any)?.isAnonymous) || String(metadata.isAnonymous || "").toLowerCase() === "true";
      const next = await recomputeSubscriberContributionStats(fundId, email, {
        ...existing,
        // Don't write the gifter's name on anonymous opt-ins. Even if
        // they type one in the form, the privacy promise binds.
        name: giftIsAnonymous ? null : (String(req.body?.name || gift?.senderName || metadata.senderName || existing?.name || "").trim() || existing?.name || null),
        optedInAt: existing?.optedInAt || new Date().toISOString(),
        unsubscribed: false,
        unsubscribedAt: null,
        // Once anonymous, always anonymous for this subscriber record.
        // A second non-anonymous gift from the same email shouldn't
        // un-anonymize the subscriber in the parent's view (would
        // retroactively reveal who the original anonymous gifter was).
        isAnonymous: existing?.isAnonymous || giftIsAnonymous,
      });

      subscribers[email] = next;
      store.subscribersByFund[fundId] = subscribers;
      store.settingsByFund[fundId] = normalizeGifterNotificationSettings(store.settingsByFund[fundId]);
      await saveGifterNotificationStore(store);

      await appendGifterNotificationQueue({
        type: "gifter_opt_in",
        fundId,
        email,
        sessionId,
        senderName: next.name,
      });
      void runGifterNotificationWorker();

      res.json({
        success: true,
        fundId,
        childName: fund.recipientFirstName || fund.name || "their child",
        email,
        optedInAt: next.optedInAt,
      });
    } catch (error) {
      console.error("Error saving gifter opt-in:", error);
      res.status(500).json({ error: "Failed to save notification preference" });
    }
  });

  app.post('/api/gifter-notifications/receipt', async (req, res) => {
    try {
      const sessionId = String(req.body?.sessionId || "").trim();
      if (!sessionId) return res.status(400).json({ error: "sessionId is required." });

      const session = await stripeService.getCheckoutSession(sessionId);
      const metadata: any = session.metadata || {};
      if (metadata.type !== "gift") {
        return res.status(400).json({ error: "Only gift checkouts can trigger a gifter receipt email." });
      }
      if (session.payment_status !== "paid") {
        return res.status(409).json({ error: "This gift has not finished processing yet." });
      }

      const paymentIntentId = typeof session.payment_intent === "string" ? session.payment_intent : session.payment_intent?.id;
      const gift = paymentIntentId ? await storage.getGiftByPaymentIntent(paymentIntentId) : undefined;
      const fundId = String(gift?.fundId || metadata.fundId || "").trim();
      if (!fundId) return res.status(404).json({ error: "Fund not found for this gift." });

      const fund = await storage.getFund(fundId);
      if (!fund) return res.status(404).json({ error: "Fund not found." });

      const email = String(gift?.senderEmail || metadata.senderEmail || req.body?.email || "").trim().toLowerCase();
      if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        return res.status(400).json({ error: "A valid gifter email is required." });
      }

      const baseUrl = getAppBaseUrl(req);
      const sourceParams = new URLSearchParams({
        ref: `gift-success:${fundId || "unknown"}`,
        src: "gift_receipt_email",
        loop_touchpoint: "gift_receipt_email",
        loop_channel: "email",
        gift_session_id: sessionId,
      });

      let eventName: string | null = null;
      const giftEventId = String(gift?.eventId || metadata.eventId || "").trim();
      if (giftEventId) {
        try {
          const ev = await storage.getEvent(giftEventId);
          if (ev?.name) eventName = ev.name;
        } catch {}
      }

      // Receipt-grade enrichment (2026-05-19 — gifter polish for the
      // sophisticated-gifter persona). Pull the Stripe charge details
      // so the receipt email can carry a real CPA-readable reference
      // block (charge date, payment method, total charged), not just
      // warm prose. All fields are nullable — if any lookup fails the
      // receipt downgrades gracefully to the prior warm-prose version
      // without the structured block.
      let paymentMethodBrand: string | null = null;
      let paymentMethodLast4: string | null = null;
      let totalChargedCents: number | null = null;
      let chargedAtIso: string | null = null;
      let receiptReference: string | null = null;
      try {
        if (paymentIntentId && typeof paymentIntentId === "string") {
          // Short reference for the receipt header — last 8 chars of
          // the Stripe payment_intent ID, uppercased. Unique enough
          // for the user to reference in support without exposing the
          // full PI ID. Matches the pattern Stripe's own receipts use.
          receiptReference = paymentIntentId.slice(-8).toUpperCase();
        }
        if (session?.created) {
          chargedAtIso = new Date(session.created * 1000).toISOString();
        }
        if (typeof session?.amount_total === "number") {
          totalChargedCents = session.amount_total;
        }
        // Payment-method lookup: card brand + last4. Same pattern the
        // recurringContributionWorker uses (line 138-147). One extra
        // Stripe call per receipt is negligible.
        const piRaw = (session as any)?.payment_intent;
        const piObj = typeof piRaw === "object" && piRaw !== null ? piRaw : null;
        const pmField = piObj?.payment_method;
        const pmId = typeof pmField === "string"
          ? pmField
          : (pmField && typeof pmField === "object" && typeof (pmField as any).id === "string")
            ? (pmField as any).id
            : null;
        if (pmId) {
          const pm: any = await stripeService.getPaymentMethod(pmId).catch(() => null);
          if (pm?.card?.brand) paymentMethodBrand = String(pm.card.brand);
          if (pm?.card?.last4) paymentMethodLast4 = String(pm.card.last4);
          if (!pm?.card && pm?.type === "us_bank_account") {
            paymentMethodBrand = "ACH bank transfer";
          }
        }
      } catch (err) {
        console.warn("[gift-receipt] Stripe enrichment failed (non-fatal):", err);
      }

      // Sponsorship eligibility lookup. Added 2026-05-25 so the receipt
      // email can include a soft Sponsor-Plus CTA when (and ONLY when)
      // the recipient fund is on the Free tier. The check happens here
      // (server-side at queue time) rather than at render time so the
      // worker stays sync + pure. Failure is non-fatal: if the lookup
      // errors, eligible defaults to false and the CTA simply doesn't
      // render.
      let eligibleForSponsorship = false;
      try {
        const fundCoverageForReceipt = await getFundCoverageState(fund.userId, fund.id);
        eligibleForSponsorship =
          fundCoverageForReceipt !== 'covered_family' &&
          fundCoverageForReceipt !== 'covered_starter' &&
          fundCoverageForReceipt !== 'trial_active';
      } catch (err) {
        console.warn("[gift-receipt] coverage lookup failed (non-fatal, CTA skipped):", err);
      }

      await appendGifterNotificationQueue({
        id: `gift_receipt_followup:${sessionId}`,
        type: "gift_receipt_followup",
        fundId,
        sessionId,
        email,
        senderName: String(gift?.senderName || metadata.senderName || "").trim() || null,
        childName: fund.recipientFirstName || fund.name || "their child",
        fundName: fund.name || fund.recipientFirstName || "their fund",
        amount: Number(gift?.amount || metadata.baseAmount || metadata.amount || 0),
        ticker: String(gift?.selectedTicker || metadata.selectedTicker || metadata.ticker || "").trim().toUpperCase() || null,
        giftUrl: fund.slug ? `${baseUrl}/${fund.slug}` : `${baseUrl}/gift/${fund.id}`,
        startFundUrl: `${baseUrl}/get-started?${sourceParams.toString()}`,
        // Sponsor-Plus deep link — opens GiftCheckout with the sponsor
        // sidebar surfaced. Renderer only inserts the CTA when
        // eligibleForSponsorship is true.
        sponsorUrl: fund.slug
          ? `${baseUrl}/${fund.slug}?sponsor=1&src=gift_receipt_email`
          : `${baseUrl}/gift/${fund.id}?sponsor=1&src=gift_receipt_email`,
        eligibleForSponsorship,
        eventName,
        // Receipt-grade enrichment fields. All nullable; renderer
        // gracefully degrades to warm-prose-only when missing.
        receiptReference,
        chargedAtIso,
        paymentMethodBrand,
        paymentMethodLast4,
        totalChargedCents,
      });
      void runGifterNotificationWorker();

      res.json({
        success: true,
        sessionId,
        fundId,
        email,
      });
    } catch (error) {
      console.error("Error queueing gifter receipt email:", error);
      res.status(500).json({ error: "Failed to queue gifter receipt email" });
    }
  });

  app.get('/api/funds/:fundId/gifter-notifications', isAuthenticated, async (req: any, res) => {
    try {
      const fund = await storage.getFund(req.params.fundId);
      if (!fund) return res.status(404).json({ error: "Fund not found" });
      // Access enforced by requireOwnedFundParam (owner or accepted collaborator).

      const store = await loadGifterNotificationStore();
      const settings = await getGifterNotificationSettingsForFund(fund.id);
      const allRecords = Object.values(store.subscribersByFund[fund.id] || {})
        .sort((a, b) => (b.lastGiftAt || "").localeCompare(a.lastGiftAt || ""));

      // Partition into named vs anonymous. Named subscribers return
      // full identifying info to the parent. Anonymous subscribers
      // never surface their email or name — the system keeps these
      // for sending notifications, but the parent surface only sees
      // an aggregate count + (optionally) anonymized rows. Per
      // feedback_anonymous_as_explicit_flag.md sub-rule on extending
      // the privacy promise to adjacent affordances.
      const namedSubscribers = allRecords
        .filter((subscriber) => !subscriber.isAnonymous)
        .map((subscriber) => ({
          email: subscriber.email,
          name: subscriber.name,
          contributionCount: subscriber.contributionCount,
          totalContributed: subscriber.totalContributed,
          optedInAt: subscriber.optedInAt,
          unsubscribed: subscriber.unsubscribed,
          lastGiftAt: subscriber.lastGiftAt,
          isAnonymous: false,
        }));

      const anonymousActiveCount = allRecords
        .filter((subscriber) => subscriber.isAnonymous && !subscriber.unsubscribed)
        .length;
      const anonymousTotalCount = allRecords
        .filter((subscriber) => subscriber.isAnonymous)
        .length;

      const transition = getAgeMilestoneState(fund.recipientBirthdate, Number((fund as any).majorityAge) || 18);

      res.json({
        fundId: fund.id,
        childName: fund.recipientFirstName || fund.name || "your child",
        settings,
        // `subscribers` array now contains ONLY named subscribers.
        // Anonymous ones are summarized in `anonymousActiveCount` /
        // `anonymousTotalCount` so the UI can render "+ X anonymous
        // subscribers" without any identifying detail.
        subscribers: namedSubscribers,
        optedInCount: namedSubscribers.filter((subscriber) => !subscriber.unsubscribed).length + anonymousActiveCount,
        anonymousActiveCount,
        anonymousTotalCount,
        nextBirthdayLabel: fund.recipientBirthdate
          ? new Date(fund.recipientBirthdate).toLocaleDateString("en-US", { month: "long", day: "numeric" })
          : null,
        age18Label: transition.eighteenthBirthday ? new Date(transition.eighteenthBirthday).toLocaleDateString("en-US") : null,
      });
    } catch (error) {
      console.error("Error fetching gifter notifications:", error);
      res.status(500).json({ error: "Failed to fetch gifter notification settings" });
    }
  });

  app.patch('/api/funds/:fundId/gifter-notifications/settings', isAuthenticated, async (req: any, res) => {
    try {
      const fund = await storage.getFund(req.params.fundId);
      if (!fund) return res.status(404).json({ error: "Fund not found" });
      if (req.fundAccessRole !== 'owner') return res.status(403).json({ error: "Forbidden" });

      const store = await loadGifterNotificationStore();
      const current = normalizeGifterNotificationSettings(store.settingsByFund[fund.id]);
      const next = normalizeGifterNotificationSettings({
        ...current,
        birthdayReminders: Object.prototype.hasOwnProperty.call(req.body ?? {}, "birthdayReminders")
          ? Boolean(req.body.birthdayReminders)
          : current.birthdayReminders,
        memoryBookSharing: Object.prototype.hasOwnProperty.call(req.body ?? {}, "memoryBookSharing")
          ? Boolean(req.body.memoryBookSharing)
          : current.memoryBookSharing,
        age18Notification: Object.prototype.hasOwnProperty.call(req.body ?? {}, "age18Notification")
          ? Boolean(req.body.age18Notification)
          : current.age18Notification,
        giftConfirmations: Object.prototype.hasOwnProperty.call(req.body ?? {}, "giftConfirmations")
          ? Boolean(req.body.giftConfirmations)
          : current.giftConfirmations,
        updatedAt: new Date().toISOString(),
      });
      store.settingsByFund[fund.id] = next;
      await saveGifterNotificationStore(store);
      res.json(next);
    } catch (error) {
      console.error("Error updating gifter notification settings:", error);
      res.status(500).json({ error: "Failed to update settings" });
    }
  });

  // Owner-initiated removal of a named gifter subscriber. The gifter can already
  // self-unsubscribe via their emailed token; this lets the fund OWNER take
  // someone off the milestone-notification list (stale address, or at the
  // gifter's verbal request). Marks unsubscribed rather than deleting — matches
  // the token-unsubscribe path + the `!unsubscribed` filters, and preserves the
  // gifter's contribution history/stats. Owner-only; anonymous subscribers have
  // no email to target and are never individually removable.
  app.post('/api/funds/:fundId/gifter-notifications/remove', isAuthenticated, async (req: any, res) => {
    try {
      const fund = await storage.getFund(req.params.fundId);
      if (!fund) return res.status(404).json({ error: "Fund not found" });
      if (req.fundAccessRole !== 'owner') return res.status(403).json({ error: "Forbidden" });
      const email = String(req.body?.email || "").trim().toLowerCase();
      // restore=true is the client's Undo path — flip the subscriber back on.
      // Reuses this endpoint so removal stays a one-tap action with a brief undo
      // window rather than a confirm gate.
      const restore = req.body?.restore === true;
      if (!email) return res.status(400).json({ error: "email is required" });
      const store = await loadGifterNotificationStore();
      const fundSubs = store.subscribersByFund[fund.id] || {};
      // Records are keyed by email; match case-insensitively to be safe.
      const key = Object.keys(fundSubs).find((k) => k.toLowerCase() === email);
      const subscriber = key ? fundSubs[key] : undefined;
      if (!subscriber || subscriber.isAnonymous) {
        return res.status(404).json({ error: "Subscriber not found" });
      }
      store.subscribersByFund[fund.id][key!] = restore
        ? { ...subscriber, unsubscribed: false }
        : { ...subscriber, unsubscribed: true, unsubscribedAt: new Date().toISOString() };
      await saveGifterNotificationStore(store);
      res.json({ success: true, email: key, restored: restore });
    } catch (error) {
      console.error("Error removing gifter subscriber:", error);
      res.status(500).json({ error: "Failed to remove subscriber" });
    }
  });

  app.post('/api/funds/:fundId/gifter-notifications/memory-share', isAuthenticated, async (req: any, res) => {
    try {
      const fund = await storage.getFund(req.params.fundId);
      if (!fund) return res.status(404).json({ error: "Fund not found" });
      if (req.fundAccessRole !== 'owner') return res.status(403).json({ error: "Forbidden" });

      const message = String(req.body?.message || "").trim();
      const photoUrl = req.body?.photoUrl ? normalizeHttpUrl(req.body.photoUrl) : null;
      if (!message) return res.status(400).json({ error: "Write a message to share." });
      if (req.body?.photoUrl && !photoUrl) return res.status(400).json({ error: "Photo URL must be a valid http(s) link." });
      // Test-pattern + boilerplate rejection. Same allowlist as the
      // Memory Book entry filter, the Activity feed filter, and the
      // server-side ensureMemoryEntryForGift guard. Without this,
      // a parent who QA'd the composer with "test test" or "aaaaaa"
      // produced a permanent share row AND burned one of their four
      // yearly cap slots — even after we filter the row at the render
      // layer, the cap counter still reflects the bad slot. Single
      // rule, four surfaces.
      const messageCompact = message.replace(/\s+/g, "");
      const isTestPattern = /^(test|testing|tstgin|tstng|qqqqq|tester)\b/i.test(message)
        || /^auto-invest contribution to /i.test(message)
        || /^([a-z])\1{2,}$/i.test(messageCompact);
      if (isTestPattern) {
        return res.status(400).json({
          error: "That looks like a test message. Updates count toward your yearly cap and reach gifters' inboxes. Try writing a real message.",
        });
      }

      const store = await loadGifterNotificationStore();
      const settings = normalizeGifterNotificationSettings(store.settingsByFund[fund.id]);
      const currentYear = new Date().getFullYear();
      if (settings.memoryBookShareYear !== currentYear) {
        settings.memoryBookShareYear = currentYear;
        settings.memoryBookSharesSentThisYear = 0;
      }
      if (settings.memoryBookSharesSentThisYear >= 4) {
        return res.status(409).json({ error: "You have already shared 4 Memory Book updates this year." });
      }

      const subscribers = Object.values(store.subscribersByFund[fund.id] || {}).filter(
        (subscriber) => !subscriber.unsubscribed,
      );
      const token = crypto.randomBytes(18).toString("hex");
      const parentName = String((req.user as any).preferredName || "").trim()
        || [String((req.user as any).firstName || "").trim(), String((req.user as any).lastName || "").trim()].filter(Boolean).join(" ")
        || null;

      store.memorySharesByToken[token] = {
        token,
        fundId: fund.id,
        message,
        photoUrl,
        childName: fund.recipientFirstName || fund.name || "your child",
        parentName,
        parentMessage: message,
        startFundUrl: `${getAppBaseUrl(req)}/get-started?${new URLSearchParams({
          ref: `gift-success:${fund.id}`,
          src: "memory_book_share_email",
          loop_touchpoint: "memory_book_share_email",
          loop_channel: "email",
        }).toString()}`,
        createdAt: new Date().toISOString(),
        recipientCount: subscribers.length,
      };
      settings.memoryBookSharesSentThisYear += 1;
      settings.updatedAt = new Date().toISOString();
      store.settingsByFund[fund.id] = settings;
      await saveGifterNotificationStore(store);

      const shareUrl = `${getAppBaseUrl(req)}/updates/share/${token}`;
      for (const subscriber of subscribers) {
        await appendGifterNotificationQueue({
          type: "memory_book_share",
          fundId: fund.id,
          email: subscriber.email,
          name: subscriber.name,
          childName: fund.recipientFirstName || fund.name || "your child",
          shareUrl,
          startFundUrl: `${getAppBaseUrl(req)}/get-started?${new URLSearchParams({
            ref: `gift-success:${fund.id}`,
            src: "memory_book_share_email",
            loop_touchpoint: "memory_book_share_email",
            loop_channel: "email",
          }).toString()}`,
          unsubscribeToken: subscriber.unsubscribeToken,
        });
      }

      res.json({
        success: true,
        shareUrl,
        recipientCount: subscribers.length,
        sharesSentThisYear: settings.memoryBookSharesSentThisYear,
      });
    } catch (error) {
      console.error("Error creating Memory Book share:", error);
      res.status(500).json({ error: "Failed to create Memory Book share" });
    }
  });

  // List the parent's past Memory Book shares for a given fund. Auth-gated to
  // the fund owner. Used by the "Past updates" section in the share modal so
  // parents can see what they sent before — message, photo, recipient count,
  // when — and re-share the same link if needed. No delivery/open metrics
  // (the worker doesn't track those today).
  app.get('/api/funds/:fundId/gifter-notifications/memory-shares', isAuthenticated, async (req: any, res) => {
    try {
      const fund = await storage.getFund(req.params.fundId);
      if (!fund) return res.status(404).json({ error: "Fund not found" });
      // Access enforced by requireOwnedFundParam (owner or accepted collaborator).

      const store = await loadGifterNotificationStore();
      const baseUrl = getAppBaseUrl(req);
      const shares = Object.values(store.memorySharesByToken || {})
        .filter((s) => s && s.fundId === fund.id)
        .map((s) => ({
          token: s.token,
          message: s.message,
          photoUrl: s.photoUrl || null,
          recipientCount: s.recipientCount ?? 0,
          createdAt: s.createdAt,
          shareUrl: `${baseUrl}/updates/share/${s.token}`,
        }))
        .sort((a, b) => (b.createdAt || "").localeCompare(a.createdAt || ""));

      res.json({ shares });
    } catch (error) {
      console.error("Error listing Memory Book shares:", error);
      res.status(500).json({ error: "Failed to list shares" });
    }
  });

  app.get('/api/gifter-notifications/share/:token', async (req, res) => {
    try {
      const store = await loadGifterNotificationStore();
      const share = store.memorySharesByToken[String(req.params.token || "").trim()];
      if (!share) return res.status(404).json({ error: "Share not found" });

      const fund = await storage.getFund(share.fundId);
      if (!fund) return res.status(404).json({ error: "Fund not found" });
      const ensuredFund = await ensureFundSlugAndPermanentEvent(fund, fund.userId);
      res.json({
        token: share.token,
        childName: share.childName,
        parentName: share.parentName,
        message: share.message,
        photoUrl: share.photoUrl,
        createdAt: share.createdAt,
        recipientCount: share.recipientCount,
        giftUrl: `/${ensuredFund.slug}`,
        startFundUrl: share.startFundUrl || `${getAppBaseUrl(req)}/get-started?${new URLSearchParams({
          ref: `gift-success:${fund.id}`,
          src: "memory_book_share_email",
          loop_touchpoint: "memory_book_share_email",
          loop_channel: "web",
        }).toString()}`,
      });
    } catch (error) {
      console.error("Error loading memory share:", error);
      res.status(500).json({ error: "Failed to load shared update" });
    }
  });

  app.post('/api/gifter-notifications/unsubscribe/:token', async (req, res) => {
    try {
      const found = await findSubscriberByUnsubscribeToken(String(req.params.token || "").trim());
      if (!found) return res.status(404).json({ error: "Subscriber not found" });

      const { store, fundId, email, subscriber } = found;
      store.subscribersByFund[fundId] = store.subscribersByFund[fundId] || {};
      store.subscribersByFund[fundId][email] = {
        ...subscriber,
        unsubscribed: true,
        unsubscribedAt: new Date().toISOString(),
      };
      await saveGifterNotificationStore(store);
      res.json({ success: true, email });
    } catch (error) {
      console.error("Error unsubscribing gifter:", error);
      res.status(500).json({ error: "Failed to unsubscribe" });
    }
  });

  app.post('/api/gifter-account/save-fund', isAuthenticated, async (req: any, res) => {
    try {
      const userId = String((req.user as any).id || "");
      const sessionId = String(req.body?.sessionId || "").trim();
      let fundId = String(req.body?.fundId || "").trim();
      let source = String(req.body?.source || "").trim() || null;

      if (!fundId && sessionId) {
        const session = await stripeService.getCheckoutSession(sessionId);
        const metadata: any = session.metadata || {};
        if (metadata.type !== "gift") {
          return res.status(400).json({ error: "Only gift sessions can save a fund." });
        }
        fundId = String(metadata.fundId || "").trim();
        source = source || "gift_success";
      }

      if (!fundId) return res.status(400).json({ error: "fundId is required." });

      const fund = await storage.getFund(fundId);
      if (!fund) return res.status(404).json({ error: "Fund not found." });

      await saveFundForGifter(userId, fund.id, source);
      res.json({ ok: true, fundId: fund.id, childName: fund.recipientFirstName || fund.name });
    } catch (error) {
      console.error("Error saving fund for gifter:", error);
      res.status(500).json({ error: "Failed to save fund." });
    }
  });

  // Gifter-dashboard follow-updates toggle.
  //
  // Added 2026-05-25 after the gifter-dashboard audit found the "You are
  // not following updates for this fund yet" status was a dead-end — the
  // copy said something was wrong but offered no action. The existing
  // /api/gifter-notifications/opt-in endpoint required a fresh Stripe
  // sessionId (post-checkout flow); a gifter on their dashboard wanting
  // to follow a saved fund has no sessionId at hand. This endpoint is
  // the dashboard-native version: authenticated gifter + fundId in the
  // path, no sessionId needed.
  //
  // Behavior: creates the subscriber row if missing OR flips
  // unsubscribed/unsubscribedAt to (false / null) on the existing row.
  // Idempotent — calling on an already-following fund returns ok=true
  // without side effects.
  //
  // Anonymous-gift discipline: this endpoint should NEVER reveal that a
  // given email previously gave anonymously to this fund. Since the
  // gifter is signed in with the same email they used to gift, the
  // existing isAnonymous flag on the subscriber row is preserved (does
  // not flip back to non-anonymous just because they pressed Follow).
  app.post('/api/gifter-account/funds/:fundId/follow', isAuthenticated, async (req: any, res) => {
    try {
      const email = String((req.user as any).email || "").trim().toLowerCase();
      const fundId = String(req.params?.fundId || "").trim();
      if (!email) return res.status(400).json({ error: "Account email is required." });
      if (!fundId) return res.status(400).json({ error: "fundId is required." });

      const fund = await storage.getFund(fundId);
      if (!fund) return res.status(404).json({ error: "Fund not found." });

      const store = await loadGifterNotificationStore();
      const subscribers = store.subscribersByFund[fundId] || {};
      const existing = subscribers[email];

      const next = await recomputeSubscriberContributionStats(fundId, email, {
        ...existing,
        name: existing?.name ?? (((req.user as any).firstName as string | undefined) || null),
        optedInAt: existing?.optedInAt || new Date().toISOString(),
        unsubscribed: false,
        unsubscribedAt: null,
        isAnonymous: existing?.isAnonymous || false,
      });

      subscribers[email] = next;
      store.subscribersByFund[fundId] = subscribers;
      store.settingsByFund[fundId] = normalizeGifterNotificationSettings(store.settingsByFund[fundId]);
      await saveGifterNotificationStore(store);

      res.json({ ok: true, fundId, updatesEnabled: true });
    } catch (error) {
      console.error("Error following fund for gifter:", error);
      res.status(500).json({ error: "Failed to follow updates." });
    }
  });

  // Symmetric unfollow. Used by the dashboard "Following" button to flip
  // OFF without emailing the user a one-time unsubscribe token. The
  // public /api/gifter-notifications/unsubscribe/:token route still
  // exists for email-link-driven unsubscription and stays unchanged.
  app.post('/api/gifter-account/funds/:fundId/unfollow', isAuthenticated, async (req: any, res) => {
    try {
      const email = String((req.user as any).email || "").trim().toLowerCase();
      const fundId = String(req.params?.fundId || "").trim();
      if (!email) return res.status(400).json({ error: "Account email is required." });
      if (!fundId) return res.status(400).json({ error: "fundId is required." });

      const store = await loadGifterNotificationStore();
      const subscribers = store.subscribersByFund[fundId] || {};
      const existing = subscribers[email];
      if (!existing) {
        // No row to flip — treat as success (idempotent).
        return res.json({ ok: true, fundId, updatesEnabled: false });
      }
      subscribers[email] = {
        ...existing,
        unsubscribed: true,
        unsubscribedAt: new Date().toISOString(),
      };
      store.subscribersByFund[fundId] = subscribers;
      await saveGifterNotificationStore(store);

      res.json({ ok: true, fundId, updatesEnabled: false });
    } catch (error) {
      console.error("Error unfollowing fund for gifter:", error);
      res.status(500).json({ error: "Failed to unfollow updates." });
    }
  });

  app.get('/api/gifter-account/dashboard', isAuthenticated, async (req: any, res) => {
    try {
      const userId = String((req.user as any).id || "");
      const email = String((req.user as any).email || "").trim().toLowerCase();
      const store = await loadGifterAccountStore();
      const record = normalizeGifterAccountRecord(userId, store.byUserId[userId]);
      const savedFundIds = Object.keys(record.savedFunds);
      const notificationStore = await loadGifterNotificationStore();

      let giftRows: any[] = [];
      if (email) {
        giftRows = (await db.execute(sql`
          SELECT
            g.fund_id,
            g.amount,
            g.created_at
          FROM gifts g
          WHERE LOWER(COALESCE(g.sender_email, '')) = ${email}
          ORDER BY g.created_at DESC
        `)).rows as any[];
      }

      const statsByFund = new Map<string, { totalGifted: number; giftCount: number; lastGiftAt: string | null }>();
      for (const row of giftRows) {
        const fundId = String(row.fund_id || "");
        const current = statsByFund.get(fundId) || { totalGifted: 0, giftCount: 0, lastGiftAt: null };
        current.totalGifted += Number(row.amount || 0);
        current.giftCount += 1;
        current.lastGiftAt = current.lastGiftAt || row.created_at || null;
        statsByFund.set(fundId, current);
      }

      const allFundIds = Array.from(new Set([...savedFundIds, ...Array.from(statsByFund.keys())]));
      const fundRecords = await Promise.all(allFundIds.map(async (fundId) => storage.getFund(fundId)));
      const fundsPayload = fundRecords
        .filter((fund) => Boolean(fund))
        .map(async (fund: any) => {
          const stats = statsByFund.get(fund.id) || { totalGifted: 0, giftCount: 0, lastGiftAt: null };
          const ageInfo = getKidAgePhase(fund.recipientBirthdate, Number((fund as any).majorityAge) || 18);
          const holdingsForFund = await storage.getHoldingsByFund(fund.id);
          // Memory preview MUST go through storage.getMemoryEntriesByFund
          // not a direct table SELECT — the storage helper applies the
          // locked filters from feedback_memory_book_inversion:
          //   1. Excludes moderation_status IN ('hidden','removed','escalated')
          //   2. Excludes the silent-gift template "X sent a gift of $Y."
          //   3. Excludes the legacy auto-invest boilerplate
          // The previous direct-SELECT bypassed all three filters and
          // surfaced junk like "Someone who loves Emma sent a gift of
          // $50.00." as the "Latest Memory Book moment" on the gifter
          // dashboard — exactly the failure the locked filters exist
          // to prevent. User flagged this 2026-05-23.
          const filteredEntries = await storage.getMemoryEntriesByFund(fund.id);
          const recentMemory = filteredEntries[0]
            ? {
                content: filteredEntries[0].content,
                authorName: filteredEntries[0].authorName,
                createdAt: filteredEntries[0].createdAt,
              }
            : undefined;
          const [activeEventCountRow] = await db
            .select({ count: sql<number>`count(*)::int` })
            .from(events)
            .where(and(eq(events.fundId, fund.id), eq(events.status, "active")));
          const currentFundValue = Number(fund.balance || 0) + Number(fund.pendingBalance || 0);
          const nextMilestoneTarget = [100, 500, 1000, 2500].find((target) => Number(stats.totalGifted || 0) < target) || null;
          const nextMilestoneProgress = nextMilestoneTarget
            ? Math.max(0, Math.min(100, (Number(stats.totalGifted || 0) / nextMilestoneTarget) * 100))
            : 100;
          const subscriber = email
            ? notificationStore.subscribersByFund?.[fund.id]?.[email] || null
            : null;

          // 30-day balance sparkline — added 2026-05-19 as the gifter-side
          // Read-Only Fund Tracking enrichment from the Five Towns roadmap.
          // Pulls snapshots from the last 30 days for this fund so the
          // Gifter Dashboard card can render a small SVG sparkline showing
          // recent fund trajectory. Same data source as the parent
          // Dashboard's trend chart — exposed to gifters because total
          // balance is ALREADY exposed (currentFundValue above); adding
          // 30-day history is the same domain, not a step-change in
          // privacy. No PII (no gifter names, no per-position breakdown);
          // just the total fund value over time.
          const thirtyDaysAgoIso = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();
          let valueHistory30d: Array<{ at: string; totalValue: number }> = [];
          try {
            const snapRes = await db.execute(sql`
              SELECT snapshot_date, total_value
              FROM fund_snapshots
              WHERE fund_id = ${fund.id}
                AND snapshot_date >= ${thirtyDaysAgoIso}
              ORDER BY snapshot_date ASC
            `);
            valueHistory30d = ((snapRes.rows as any[]) || []).map((r) => ({
              at: new Date(r.snapshot_date).toISOString(),
              totalValue: Number(r.total_value || 0),
            }));
          } catch (err) {
            // Non-fatal — sparkline gracefully renders nothing if data
            // missing. Card still shows currentFundValue.
            console.warn("[gifter-dashboard] sparkline fetch failed:", err);
          }

          // Sponsorship eligibility per fund. True when the fund is on
          // the Free tier (i.e., the gifter could meaningfully cover a
          // year of Plus or Family for the family). False when the fund
          // already has Plus / Family / trial coverage. Per
          // project_gifter_sponsors_plus_subscription.md (locked
          // 2026-05-23) — sponsorship is annual-only and only mints
          // value when the underlying fund isn't already on a paid
          // tier. Adding this to the dashboard response 2026-05-25 so
          // the per-fund card can render a contextual sponsor pill
          // when applicable, replacing the previously-removed
          // 'discovery card' that made a false claim about scrolling
          // up to find the option.
          let eligibleForSponsorship = false;
          try {
            const fundCoverage = await getFundCoverageState(fund.userId, fund.id);
            eligibleForSponsorship =
              fundCoverage !== 'covered_family' &&
              fundCoverage !== 'covered_starter' &&
              fundCoverage !== 'trial_active';
          } catch (err) {
            // Non-fatal — pill simply doesn't render on this fund.
            console.warn("[gifter-dashboard] coverage lookup failed:", err);
          }

          return {
            fundId: fund.id,
            childName: fund.recipientFirstName || fund.name,
            fundName: fund.name,
            sharePath: buildFundSharePath(fund),
            totalGifted: Number(stats.totalGifted.toFixed(2)),
            giftCount: stats.giftCount,
            lastGiftAt: stats.lastGiftAt,
            savedAt: record.savedFunds[fund.id]?.savedAt || null,
            savedSource: record.savedFunds[fund.id]?.source || null,
            nextBirthdayLabel: fund.recipientBirthdate
              ? new Date(fund.recipientBirthdate).toLocaleDateString("en-US", { month: "long", day: "numeric" })
              : null,
            // Birthdate + majorityAge added 2026-05-21 so the gifter
            // dashboard can compute per-gift / per-relationship projected
            // impact ("Your $1,500 to Haley could be worth ~$X when she
            // turns 21"). Treatment 3 of the five DUNPHY_DEMO_SPEC.md
            // projection treatments. Same data the parent dashboard
            // already exposes; not a privacy step-change for the gifter
            // surface — birthdate ALREADY round-trips via nextBirthdayLabel.
            recipientBirthdate: fund.recipientBirthdate
              ? new Date(fund.recipientBirthdate).toISOString().slice(0, 10)
              : null,
            majorityAge: Number((fund as any).majorityAge) || 18,
            childPhase: ageInfo.phase,
            fundStatus: String(fund.status || "draft"),
            currentFundValue: Number(currentFundValue.toFixed(2)),
            holdingsCount: holdingsForFund.filter((holding) => Number(holding.currentValue || 0) > 0).length,
            activeEventCount: Number(activeEventCountRow?.count || 0),
            nextMilestoneTarget,
            nextMilestoneProgress: Number(nextMilestoneProgress.toFixed(1)),
            recentMemoryPreview: recentMemory?.content ? String(recentMemory.content).slice(0, 140) : null,
            recentMemoryAuthor: recentMemory?.authorName ? String(recentMemory.authorName) : null,
            recentMemoryAt: recentMemory?.createdAt ? new Date(recentMemory.createdAt).toISOString() : null,
            updatesEnabled: Boolean(subscriber && !subscriber.unsubscribed),
            eligibleForSponsorship,
            valueHistory30d,
          };
        });

      const resolvedFundsPayload = (await Promise.all(fundsPayload))
        .sort((a, b) => {
          const aTs = new Date(a.lastGiftAt || a.savedAt || 0).getTime();
          const bTs = new Date(b.lastGiftAt || b.savedAt || 0).getTime();
          return bTs - aTs;
        });

      // Sponsor-Plus history — the gifter's active + past sponsored
      // Plus/Family subscriptions on other people's funds. Added 2026-05-23
      // after user flagged the gifter dashboard didn't surface the new
      // gifter-as-customer features. Joins through funds + users to
      // resolve the child + parent names for display.
      let sponsoredSubs: any[] = [];
      if (email) {
        try {
          const sponsoredRes = await db.execute(sql`
            SELECT
              ss.id, ss.fund_id, ss.tier, ss.activated_at, ss.expires_at, ss.status,
              f.name AS fund_name, f.recipient_first_name, f.slug AS fund_slug
            FROM sponsored_subscriptions ss
            JOIN funds f ON f.id = ss.fund_id
            WHERE LOWER(COALESCE(ss.sponsor_email, '')) = ${email}
            ORDER BY ss.activated_at DESC
            LIMIT 20
          `);
          sponsoredSubs = ((sponsoredRes.rows as any[]) || []).map((r) => ({
            id: String(r.id),
            fundId: String(r.fund_id),
            fundSlug: r.fund_slug || null,
            childName: r.recipient_first_name || r.fund_name || "the fund",
            tier: String(r.tier || "starter"),
            status: String(r.status || "active"),
            activatedAt: new Date(r.activated_at).toISOString(),
            expiresAt: new Date(r.expires_at).toISOString(),
          }));
        } catch (err) {
          // Non-fatal: if the table is missing (pre-migration) or the
          // query fails, just skip this section.
          console.warn("[gifter-dashboard] sponsored subs query failed:", err);
        }
      }

      // Founder-gift history — the gifter has bought Founder slots
      // for other people. Reads the .local/founding-members.jsonl
      // file and filters by sponsorEmail. Light-touch implementation
      // (file read on each request) is acceptable at expected volume
      // (<1000 lines total, only specific gifter records returned).
      let founderGifts: any[] = [];
      if (email) {
        try {
          const path = await import("path");
          const fs = await import("fs/promises");
          const FOUNDING_PATH = path.join(process.cwd(), ".local", "founding-members.jsonl");
          const text = await fs.readFile(FOUNDING_PATH, "utf8").catch((err: any) => {
            if (err?.code === "ENOENT") return "";
            throw err;
          });
          const lines = text.split("\n").filter((l) => l.trim());
          for (const line of lines) {
            try {
              const entry = JSON.parse(line);
              if (String(entry?.sponsorEmail || "").toLowerCase() === email) {
                founderGifts.push({
                  recipientName: String(entry.recipientName || entry.firstName || "a friend"),
                  recipientEmail: String(entry.recipientEmail || entry.email || ""),
                  position: Number(entry.position || 0),
                  createdAt: String(entry.createdAt || new Date().toISOString()),
                  message: entry.message ? String(entry.message) : null,
                });
              }
            } catch {
              // skip malformed line
            }
          }
          founderGifts.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
        } catch (err) {
          console.warn("[gifter-dashboard] founder gifts read failed:", err);
        }
      }

      res.json({
        summary: {
          savedFundCount: resolvedFundsPayload.length,
          totalGifted: Number(resolvedFundsPayload.reduce((sum, row) => sum + row.totalGifted, 0).toFixed(2)),
          totalGifts: resolvedFundsPayload.reduce((sum, row) => sum + row.giftCount, 0),
          trackedFundValue: Number(resolvedFundsPayload.reduce((sum, row) => sum + row.currentFundValue, 0).toFixed(2)),
          followingUpdatesCount: resolvedFundsPayload.filter((row) => row.updatesEnabled).length,
        },
        funds: resolvedFundsPayload,
        sponsoredSubs,
        founderGifts,
      });
    } catch (error) {
      console.error("Error fetching gifter dashboard:", error);
      res.status(500).json({ error: "Failed to load gifter dashboard." });
    }
  });

  // Gifter recurring schedules — list active + paused recurring_gifts
  // rows belonging to the authenticated user (matched by sender_email).
  // Powers the "Your recurring gifts" section on /gifter dashboard.
  // Per locked Decision A (project_gifter_recurring_restoration.md),
  // recurring setup REQUIRES an account so this endpoint can always
  // identify the gifter's schedules by email match.
  app.get('/api/gifter-account/recurring', isAuthenticated, async (req: any, res) => {
    try {
      const email = String((req.user as any).email || "").trim().toLowerCase();
      if (!email) return res.json({ schedules: [] });
      const rows = await db.execute(sql`
        SELECT
          rg.id,
          rg.fund_id,
          rg.sender_name,
          rg.amount,
          rg.frequency,
          rg.status,
          rg.pause_reason,
          rg.next_charge_date,
          rg.created_at,
          rg.stripe_subscription_id,
          f.name AS fund_name,
          f.slug AS fund_slug,
          f.recipient_first_name
        FROM recurring_gifts rg
        INNER JOIN funds f ON f.id = rg.fund_id
        WHERE LOWER(COALESCE(rg.sender_email, '')) = ${email}
          AND rg.status IN ('active', 'paused')
        ORDER BY rg.created_at DESC
      `);
      const schedules = ((rows.rows as any[]) || []).map((r) => ({
        id: String(r.id),
        fundId: String(r.fund_id),
        fundName: r.recipient_first_name || r.fund_name || "Fund",
        fundSlug: r.fund_slug || null,
        amount: parseFloat(String(r.amount || "0")),
        frequency: String(r.frequency || "monthly"),
        status: String(r.status || "active"),
        pauseReason: r.pause_reason ? String(r.pause_reason) : null,
        nextChargeDate: r.next_charge_date ? new Date(r.next_charge_date).toISOString() : null,
        createdAt: new Date(r.created_at).toISOString(),
        // True when the row is a real Stripe subscription that auto-charges
        // the card (Plus funds); false for reminder-only cadences (Free
        // funds) where the date is a "time to gift again" email, not a
        // charge. Lets the UI label "Next charge" vs "Next reminder".
        autoCharge: Boolean(r.stripe_subscription_id),
      }));
      res.json({ schedules });
    } catch (err) {
      console.error("Error fetching gifter recurring schedules:", err);
      res.status(500).json({ error: "Failed to load recurring schedules." });
    }
  });

  // Cancel a gifter recurring schedule. Owner-gated: the authenticated
  // user's email must match the recurring_gifts.sender_email. Cancels
  // the Stripe subscription too so no further charges fire.
  app.post('/api/gifter-account/recurring/:id/cancel', isAuthenticated, async (req: any, res) => {
    try {
      const email = String((req.user as any).email || "").trim().toLowerCase();
      const scheduleId = String(req.params.id || "");
      if (!email || !scheduleId) return res.status(400).json({ error: "Missing parameters" });

      const rows = await db.execute(sql`
        SELECT id, sender_email, stripe_subscription_id, status
        FROM recurring_gifts
        WHERE id = ${scheduleId}
        LIMIT 1
      `);
      const row = (rows.rows as any[])?.[0];
      if (!row) return res.status(404).json({ error: "Recurring schedule not found" });
      if (String(row.sender_email || "").trim().toLowerCase() !== email) {
        return res.status(403).json({ error: "Forbidden" });
      }
      if (row.stripe_subscription_id) {
        try {
          const stripe = await getUncachableStripeClient();
          await stripe.subscriptions.cancel(String(row.stripe_subscription_id));
        } catch (cancelErr) {
          console.warn("Stripe cancel failed (proceeding with local cancel):", cancelErr);
        }
      }
      await db.execute(sql`
        UPDATE recurring_gifts
        SET status = 'cancelled', pause_reason = 'user', paused_at = NOW()
        WHERE id = ${scheduleId}
      `);
      res.json({ ok: true });
    } catch (err) {
      console.error("Error cancelling gifter recurring schedule:", err);
      res.status(500).json({ error: "Failed to cancel recurring." });
    }
  });

  // ── Gifter recurring management (pause / resume / edit / history) ──
  //
  // The /api/gifter-account/recurring list returns TWO kinds of row that
  // share the recurring_gifts table:
  //   1. Stripe-backed auto-charging subscriptions (Plus-tier funds) —
  //      have stripe_subscription_id; Stripe drives billing and the
  //      invoice.paid webhook bumps next_charge_date to a FUTURE date.
  //   2. Reminder-only cadences (Free-tier funds, per pricing-v3) — no
  //      stripe_subscription_id; the recurringContributionWorker emails
  //      "time to gift again, we won't charge" when next_charge_date is due.
  // Each handler below branches on stripe_subscription_id so a pause/edit
  // never tries to mutate a Stripe sub that doesn't exist, and never
  // leaves a reminder cadence firing after the gifter paused it.
  //
  // All three mutating handlers are owner-gated by sender_email (same as
  // cancel) and wrap the Stripe call in try/catch so a transient Stripe
  // error doesn't desync the local row. Edits use proration_behavior:
  // 'none' so changing an amount/frequency NEVER triggers a surprise
  // mid-cycle charge — the new terms apply from the next cycle.
  // Locked 2026-05-26 per the gifter-dashboard level-up.

  // Shared owner-lookup. Returns the row (with the columns the handlers
  // need) when the authenticated user owns it, or sends the appropriate
  // error response and returns null.
  const loadOwnedRecurring = async (req: any, res: any) => {
    const email = String((req.user as any).email || "").trim().toLowerCase();
    const scheduleId = String(req.params.id || "");
    if (!email || !scheduleId) {
      res.status(400).json({ error: "Missing parameters" });
      return null;
    }
    const rows = await db.execute(sql`
      SELECT rg.id, rg.sender_email, rg.sender_name, rg.stripe_subscription_id,
             rg.status, rg.amount, rg.frequency, rg.fund_id,
             f.recipient_first_name, f.name AS fund_name
      FROM recurring_gifts rg
      INNER JOIN funds f ON f.id = rg.fund_id
      WHERE rg.id = ${scheduleId}
      LIMIT 1
    `);
    const row = (rows.rows as any[])?.[0];
    if (!row) {
      res.status(404).json({ error: "Recurring schedule not found" });
      return null;
    }
    if (String(row.sender_email || "").trim().toLowerCase() !== email) {
      res.status(403).json({ error: "Forbidden" });
      return null;
    }
    return row;
  };

  const RECURRING_INTERVAL: Record<string, "week" | "month" | "year"> = {
    weekly: "week",
    monthly: "month",
    yearly: "year",
  };

  // Pause: stop future charges without losing the schedule. Stripe-backed
  // rows use pause_collection behavior 'void' (invoices during the pause
  // are voided, not stacked up to back-charge on resume). Reminder-only
  // rows just flip to 'paused' so the worker's status='active' filter
  // skips them.
  app.post('/api/gifter-account/recurring/:id/pause', isAuthenticated, async (req: any, res) => {
    try {
      const row = await loadOwnedRecurring(req, res);
      if (!row) return;
      if (String(row.status) === "paused") return res.json({ ok: true, alreadyPaused: true });
      if (row.stripe_subscription_id) {
        try {
          const stripe = await getUncachableStripeClient();
          await stripe.subscriptions.update(String(row.stripe_subscription_id), {
            pause_collection: { behavior: "void" },
          });
        } catch (pauseErr) {
          console.warn("Stripe pause failed (proceeding with local pause):", pauseErr);
        }
      }
      await db.execute(sql`
        UPDATE recurring_gifts
        SET status = 'paused', pause_reason = 'user', paused_at = NOW()
        WHERE id = ${String(row.id)}
      `);
      res.json({ ok: true });
    } catch (err) {
      console.error("Error pausing gifter recurring schedule:", err);
      res.status(500).json({ error: "Failed to pause recurring." });
    }
  });

  // Resume: clear the pause. For Stripe-backed rows we clear
  // pause_collection and re-read the subscription's current_period_end so
  // the local next_charge_date matches Stripe's. For reminder-only rows we
  // advance next_charge_date one cadence forward from now so the worker
  // doesn't fire an immediate "catch-up" reminder.
  app.post('/api/gifter-account/recurring/:id/resume', isAuthenticated, async (req: any, res) => {
    try {
      const row = await loadOwnedRecurring(req, res);
      if (!row) return;
      if (String(row.status) === "active") return res.json({ ok: true, alreadyActive: true });
      let nextChargeMs: number | null = null;
      if (row.stripe_subscription_id) {
        try {
          const stripe = await getUncachableStripeClient();
          const sub = await stripe.subscriptions.update(String(row.stripe_subscription_id), {
            pause_collection: "" as any,
          });
          if ((sub as any).current_period_end) {
            nextChargeMs = Number((sub as any).current_period_end) * 1000;
          }
        } catch (resumeErr) {
          console.warn("Stripe resume failed (proceeding with local resume):", resumeErr);
        }
      }
      if (nextChargeMs) {
        await db.execute(sql`
          UPDATE recurring_gifts
          SET status = 'active', pause_reason = NULL, paused_at = NULL,
              next_charge_date = ${new Date(nextChargeMs).toISOString()}
          WHERE id = ${String(row.id)}
        `);
      } else {
        // Reminder-only (or Stripe period unavailable): advance the cadence
        // forward from now so the next reminder fires on schedule.
        const interval = RECURRING_INTERVAL[String(row.frequency)] || "month";
        const next = new Date();
        if (interval === "week") next.setDate(next.getDate() + 7);
        else if (interval === "year") next.setFullYear(next.getFullYear() + 1);
        else next.setMonth(next.getMonth() + 1);
        await db.execute(sql`
          UPDATE recurring_gifts
          SET status = 'active', pause_reason = NULL, paused_at = NULL,
              next_charge_date = ${next.toISOString()}
          WHERE id = ${String(row.id)}
        `);
      }
      res.json({ ok: true });
    } catch (err) {
      console.error("Error resuming gifter recurring schedule:", err);
      res.status(500).json({ error: "Failed to resume recurring." });
    }
  });

  // Edit amount and/or frequency. Stripe-backed rows get a fresh Price
  // (new unit_amount + interval) swapped onto the subscription item with
  // proration_behavior 'none' — the change applies from the next cycle,
  // never as an immediate prorated charge. Reminder-only rows just update
  // the suggested amount / cadence locally.
  app.post('/api/gifter-account/recurring/:id/update', isAuthenticated, async (req: any, res) => {
    try {
      const row = await loadOwnedRecurring(req, res);
      if (!row) return;
      const rawAmount = Number((req.body || {}).amount);
      const rawFrequency = String((req.body || {}).frequency || row.frequency);
      if (!Number.isFinite(rawAmount) || rawAmount < 1) {
        return res.status(400).json({ error: "Enter an amount of at least $1." });
      }
      if (rawAmount > 10000) {
        return res.status(400).json({ error: "Amount is too large for a recurring gift." });
      }
      if (!RECURRING_INTERVAL[rawFrequency]) {
        return res.status(400).json({ error: "Frequency must be weekly, monthly, or yearly." });
      }
      const amount = Math.round(rawAmount * 100) / 100;
      let nextChargeMs: number | null = null;
      if (row.stripe_subscription_id) {
        try {
          const stripe = await getUncachableStripeClient();
          const recipientName = String(row.recipient_first_name || row.fund_name || "the child");
          const price = await stripe.prices.create({
            currency: "usd",
            unit_amount: Math.round(amount * 100),
            recurring: { interval: RECURRING_INTERVAL[rawFrequency] },
            product_data: { name: `Recurring gift to ${recipientName}'s fund` },
          });
          const sub = await stripe.subscriptions.retrieve(String(row.stripe_subscription_id));
          const itemId = (sub as any).items?.data?.[0]?.id;
          if (!itemId) throw new Error("Subscription has no line item to update");
          const updated = await stripe.subscriptions.update(String(row.stripe_subscription_id), {
            items: [{ id: itemId, price: price.id }],
            proration_behavior: "none",
            metadata: {
              ...((sub as any).metadata || {}),
              amountUsd: String(amount),
              frequency: rawFrequency,
            },
          });
          if ((updated as any).current_period_end) {
            nextChargeMs = Number((updated as any).current_period_end) * 1000;
          }
        } catch (editErr) {
          console.error("Stripe recurring edit failed:", editErr);
          return res.status(502).json({ error: "Could not update the schedule with our payment processor. No changes were made." });
        }
      }
      if (nextChargeMs) {
        await db.execute(sql`
          UPDATE recurring_gifts
          SET amount = ${String(amount)}, frequency = ${rawFrequency},
              next_charge_date = ${new Date(nextChargeMs).toISOString()}
          WHERE id = ${String(row.id)}
        `);
      } else {
        await db.execute(sql`
          UPDATE recurring_gifts
          SET amount = ${String(amount)}, frequency = ${rawFrequency}
          WHERE id = ${String(row.id)}
        `);
      }
      res.json({ ok: true, amount, frequency: rawFrequency });
    } catch (err) {
      console.error("Error updating gifter recurring schedule:", err);
      res.status(500).json({ error: "Failed to update recurring." });
    }
  });

  // Charge history for one schedule. Read-only. Stripe-backed rows list
  // their paid invoices (the real charges that have flowed into the fund);
  // reminder-only rows have no charges and return reminderOnly:true so the
  // UI can say "this is a reminder, not an auto-charge."
  app.get('/api/gifter-account/recurring/:id/history', isAuthenticated, async (req: any, res) => {
    try {
      const row = await loadOwnedRecurring(req, res);
      if (!row) return;
      if (!row.stripe_subscription_id) {
        return res.json({ charges: [], totalCharged: 0, count: 0, reminderOnly: true });
      }
      const stripe = await getUncachableStripeClient();
      const invoices = await stripe.invoices.list({
        subscription: String(row.stripe_subscription_id),
        status: "paid",
        limit: 100,
      });
      const charges = (invoices.data || [])
        .map((inv: any) => {
          const paidAt = inv.status_transitions?.paid_at || inv.created;
          return {
            id: String(inv.id),
            amount: (inv.amount_paid || 0) / 100,
            at: paidAt ? new Date(Number(paidAt) * 1000).toISOString() : null,
          };
        })
        .filter((c: any) => c.amount > 0);
      const totalCharged = charges.reduce((sum: number, c: any) => sum + c.amount, 0);
      res.json({ charges, totalCharged, count: charges.length, reminderOnly: false });
    } catch (err) {
      console.error("Error fetching gifter recurring history:", err);
      res.status(500).json({ error: "Failed to load charge history." });
    }
  });

  // Gifter contribution history CSV download. Used by sophisticated
  // gifters (grandparents giving across multiple grandkids,
  // professionals tracking Form 709 gift-tax compliance) to pull a
  // year-by-year record of every gift they've made, CPA-readable.
  // Locked 2026-05-19 per the Five Towns gifter polish — see
  // project_five_towns_roadmap P5.
  //
  // Authenticated as a gifter account (registered users with a saved
  // email). The endpoint scopes by sender_email matching the
  // authenticated user's email — gifts made anonymously without a
  // saved email aren't recoverable for export because there's no
  // identity linkage to claim them.
  //
  // Output: BOM-prefixed UTF-8 CSV with Content-Disposition. Same
  // Excel-locale-safe encoding the parent Tax Documents exports use.
  // Optional ?year=YYYY filter scopes to a single calendar year for
  // Form 709 annual-exclusion reconciliation; absence returns all
  // history.
  app.get('/api/gifter-account/gifts.csv', isAuthenticated, async (req: any, res) => {
    try {
      const email = String((req.user as any).email || "").trim().toLowerCase();
      if (!email) {
        res.status(400).send("No email on account");
        return;
      }
      const yearParam = typeof req.query.year === "string" && /^\d{4}$/.test(req.query.year)
        ? String(req.query.year)
        : null;

      // Pull every gift this email has sent, with the fund's child
      // first-name so the CSV is human-readable (not just UUIDs).
      // Sender-email match is case-insensitive (gifts may have been
      // captured under different capitalizations across sessions).
      const yearStart = yearParam ? `${yearParam}-01-01` : null;
      const yearEnd = yearParam ? `${yearParam}-12-31 23:59:59` : null;
      const giftRows = (await db.execute(sql`
        SELECT
          g.id,
          g.amount,
          g.message,
          g.selected_ticker AS "selectedTicker",
          g.status,
          g.created_at AS "createdAt",
          g.settled_at AS "settledAt",
          f.recipient_first_name AS "childFirstName",
          f.recipient_last_name AS "childLastName",
          f.name AS "fundName",
          ev.name AS "eventName"
        FROM gifts g
        LEFT JOIN funds f ON f.id = g.fund_id
        LEFT JOIN events ev ON ev.id = g.event_id
        WHERE LOWER(COALESCE(g.sender_email, '')) = ${email}
          AND g.status NOT IN ('failed', 'canceled')
          ${yearStart && yearEnd ? sql`AND g.created_at >= ${yearStart} AND g.created_at <= ${yearEnd}` : sql``}
        ORDER BY g.created_at ASC
      `)).rows as any[];

      // CSV-quoting helper. Matches the pattern in Activity export +
      // Tax Documents export — wraps cells containing comma / quote /
      // newline in double quotes, doubles embedded quotes.
      const csvCell = (raw: unknown): string => {
        const s = raw == null ? "" : String(raw);
        if (/[",\n\r]/.test(s)) return `"${s.replace(/"/g, '""')}"`;
        return s;
      };

      const headers = [
        "Gift date",
        "Settled date",
        "Recipient",
        "Fund",
        "Occasion",
        "Amount (USD)",
        "Ticker",
        "Status",
        "Note",
        "Gift ID",
      ];
      const rows: string[][] = [headers];
      let totalAmount = 0;
      for (const g of giftRows) {
        const created = g.createdAt ? new Date(g.createdAt) : null;
        const settled = g.settledAt ? new Date(g.settledAt) : null;
        const childFull = [g.childFirstName, g.childLastName].filter(Boolean).join(" ").trim();
        const amount = Number(g.amount || 0);
        totalAmount += amount;
        rows.push([
          created && Number.isFinite(created.getTime()) ? created.toISOString().slice(0, 10) : "",
          settled && Number.isFinite(settled.getTime()) ? settled.toISOString().slice(0, 10) : "",
          childFull || g.childFirstName || "",
          g.fundName || "",
          g.eventName || "",
          amount.toFixed(2),
          g.selectedTicker || "",
          g.status || "",
          g.message ? String(g.message).slice(0, 500) : "",
          String(g.id || ""),
        ]);
      }
      // Footer total row — anchors the file so the gifter doesn't
      // have to sum the column themselves. Useful for Form 709
      // annual-exclusion reconciliation when filtered to a single year.
      rows.push([
        yearParam ? `TOTAL ${yearParam}` : "TOTAL (all years)",
        "",
        "",
        "",
        "",
        totalAmount.toFixed(2),
        "",
        "",
        "",
        "",
      ]);

      const body = rows.map((r) => r.map(csvCell).join(",")).join("\n");
      // BOM prefix for Excel UTF-8 locale safety (same as Tax Documents).
      const filename = yearParam
        ? `kiddo-my-gifts-${yearParam}.csv`
        : `kiddo-my-gifts-all-years.csv`;
      res.setHeader("Content-Type", "text/csv; charset=utf-8");
      res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
      res.send("﻿" + body);
    } catch (error) {
      console.error("Error generating gifter CSV:", error);
      res.status(500).send("Failed to generate CSV");
    }
  });

  app.get('/api/inbox', isAuthenticated, async (req: any, res) => {
    try {
      const userId = String((req.user as any).id || "");
      const [user] = await db
        .select({
          kycStatus: users.kycStatus,
          kycSubmittedAt: users.kycSubmittedAt,
          firstName: users.firstName,
        })
        .from(users)
        .where(eq(users.id, userId))
        .limit(1);

      const userFunds = await storage.getFundsByUser(userId);
      const requestedFundId = (req.query as any)?.fundId as string | undefined;
      const primaryFund = (requestedFundId ? userFunds.find((f) => f.id === requestedFundId) : null) || userFunds[0] || null;
      const items: Array<{
        id: string;
        tone: "info" | "success" | "warning";
        title: string;
        description: string;
        ctaLabel: string | null;
        ctaHref: string | null;
      }> = [];

      if (user?.kycStatus === "pending") {
        items.push({
          id: "kyc-pending",
          tone: "info",
          title: "Your identity check is in review",
          description: "We are reviewing your account details now. Gifts can still arrive while investing waits for approval.",
          ctaLabel: "Open activation",
          ctaHref: "/activate",
        });
      }

      if (user?.kycStatus === "failed") {
        items.push({
          id: "kyc-failed",
          tone: "warning",
          title: "Your identity details need attention",
          description: "One part of your legal information did not pass validation. Update it so the fund can start investing.",
          ctaLabel: "Fix identity details",
          ctaHref: "/activate",
        });
      }

      if (primaryFund) {
        const [giftCounts] = await db
          .select({
            settledCount: sql<number>`COUNT(*) FILTER (WHERE ${gifts.status} NOT IN ('failed', 'refunded', 'canceled'))::int`,
            pendingCount: sql<number>`COUNT(*) FILTER (WHERE ${gifts.status} IN ('pending', 'processing', 'host_hold'))::int`,
          })
          .from(gifts)
          .where(eq(gifts.fundId, primaryFund.id));

        const [memoryCounts] = await db
          .select({ count: sql<number>`count(*)::int` })
          .from(memoryEntries)
          .where(eq(memoryEntries.fundId, primaryFund.id));

        const birthday = primaryFund.recipientBirthdate ? new Date(primaryFund.recipientBirthdate) : null;
        if (birthday && !Number.isNaN(birthday.getTime())) {
          const upcoming = new Date(birthday);
          upcoming.setFullYear(new Date().getFullYear());
          if (upcoming.getTime() < Date.now()) upcoming.setFullYear(upcoming.getFullYear() + 1);
          const diffDays = Math.ceil((upcoming.getTime() - Date.now()) / (1000 * 60 * 60 * 24));
          if (diffDays >= 0 && diffDays <= 21) {
            items.push({
              id: "birthday-soon",
              tone: "info",
              title: `${primaryFund.recipientFirstName || primaryFund.name}'s birthday is coming up`,
              description: "This is the best moment to create a gifting page and give family a reason to act now.",
              ctaLabel: "Create a moment",
              ctaHref: "/event/create",
            });
          }
        }

        if (Number(giftCounts?.pendingCount || 0) > 0) {
          items.push({
            id: "gift-pending",
            tone: "info",
            title: "A gift is still moving through the system",
            description: "One or more gifts are pending, processing, or waiting on a protection check before they settle.",
            ctaLabel: "Open activity",
            ctaHref: "/activity",
          });
        }

        if (Number(giftCounts?.settledCount || 0) === 0) {
          items.push({
            id: "first-gift",
            tone: "warning",
            title: `${primaryFund.recipientFirstName || primaryFund.name}'s first gift has not landed yet`,
            description: "Share the fund once so the first gift can arrive and the story can finally begin.",
            ctaLabel: "Share fund",
            ctaHref: buildFundSharePath(primaryFund),
          });
        } else if (Number(memoryCounts?.count || 0) === 0) {
          items.push({
            id: "first-memory",
            tone: "success",
            title: "The fund has gifts. Now write the first Memory Book note.",
            description: "This is the page your child may read first someday. Give the story its opening line.",
            ctaLabel: "Open Memory Book",
            ctaHref: `/memory/${primaryFund.id}`,
          });
        }
      }

      res.json({ items: items.slice(0, 4) });
    } catch (error) {
      console.error("Error building inbox:", error);
      res.status(500).json({ error: "Failed to load inbox." });
    }
  });

