  app.post('/api/funds/activate', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const { fundId, strategy } = req.body;
      if (!fundId) {
        return res.status(400).json({ error: 'Fund ID is required' });
      }
      const fund = await storage.getFund(fundId);
      if (!fund) {
        return res.status(404).json({ error: 'Fund not found' });
      }
      // Activation is owner-only — ties to the owner's KYC and Stripe
      // subscription, plus the investment-strategy selection flows from
      // the owner's allowed plan tier.
      if (req.fundAccessRole !== 'owner') {
        return res.status(403).json({ error: 'Forbidden' });
      }
      const allowedStrategy = await resolveAllowedFundStrategy(userId, fundId, strategy);
      const updated = await storage.updateFund(fundId, {
        status: "active",
        investmentStrategy: allowedStrategy,
      });
      res.json(updated);
    } catch (error) {
      console.error('Error activating fund:', error);
      res.status(500).json({ error: 'Failed to activate fund' });
    }
  });

  // ===== TWO-FACTOR AUTH (TOTP) — account management =====
  // Opt-in per parent account. These endpoints manage ENROLLMENT only. The
  // login-time second-factor gate is enforced separately in the auth flow;
  // until that's wired, these are inert infrastructure (no UI calls them yet)
  // and non-enrolled users are unaffected (totpEnabled defaults false).
  // TOTP is RFC 6238, dependency-free, pinned to the RFC test vectors — see
  // server/totp.ts + scripts/verify-totp.ts.
  app.get('/api/auth/2fa/status', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const [row] = await db.select({ enabled: users.totpEnabled }).from(users).where(eq(users.id, userId)).limit(1);
      res.json({ enabled: Boolean(row?.enabled) });
    } catch (e) {
      console.error('[2fa] status error:', e);
      res.status(500).json({ error: 'Could not load 2FA status' });
    }
  });

  // Begin enrollment: mint a PENDING secret + return the otpauth URI for the
  // authenticator app. Does NOT enable 2FA — that requires verifying a code.
  app.post('/api/auth/2fa/setup', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const [u] = await db.select({ email: users.email, enabled: users.totpEnabled }).from(users).where(eq(users.id, userId)).limit(1);
      if (u?.enabled) return res.status(400).json({ error: 'Two-factor is already on. Turn it off first to re-enroll.' });
      const secret = generateTotpSecret();
      await db.update(users).set({ totpPendingSecret: secret, updatedAt: new Date() }).where(eq(users.id, userId));
      res.json({ secret, otpauthUri: buildOtpauthUri(u?.email || 'account', secret) });
    } catch (e) {
      console.error('[2fa] setup error:', e);
      res.status(500).json({ error: 'Could not start 2FA setup' });
    }
  });

  // Confirm enrollment: verify a live code against the pending secret. On
  // success, promote it, enable 2FA, and return one-time backup codes (shown
  // to the user once; stored only as bcrypt hashes).
  app.post('/api/auth/2fa/enable', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const code = String(req.body?.code || '');
      const [u] = await db.select({ pending: users.totpPendingSecret, enabled: users.totpEnabled }).from(users).where(eq(users.id, userId)).limit(1);
      if (u?.enabled) return res.status(400).json({ error: 'Two-factor is already on.' });
      if (!u?.pending) return res.status(400).json({ error: 'Start setup first.' });
      if (!verifyTotp(u.pending, code)) return res.status(400).json({ error: 'That code did not match. Check your authenticator and try again.' });
      const backupCodes = generateBackupCodes();
      const hashed = await hashBackupCodes(backupCodes);
      await db.update(users).set({
        totpSecret: u.pending,
        totpPendingSecret: null,
        totpEnabled: true,
        totpBackupCodes: hashed,
        updatedAt: new Date(),
      }).where(eq(users.id, userId));
      await writeAudit(req, 'totp_enabled', 'user', userId);
      res.json({ enabled: true, backupCodes });
    } catch (e) {
      console.error('[2fa] enable error:', e);
      res.status(500).json({ error: 'Could not enable 2FA' });
    }
  });

  // Turn off 2FA. Requires proof of possession: a current TOTP code OR an
  // unused backup code.
  app.post('/api/auth/2fa/disable', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const code = String(req.body?.code || '');
      const [u] = await db.select({ secret: users.totpSecret, enabled: users.totpEnabled, backup: users.totpBackupCodes }).from(users).where(eq(users.id, userId)).limit(1);
      if (!u?.enabled || !u?.secret) return res.status(400).json({ error: 'Two-factor is not on.' });
      const hashes = Array.isArray(u.backup) ? (u.backup as string[]) : [];
      const codeOk = verifyTotp(u.secret, code) || (await findBackupCodeMatch(code, hashes)) >= 0;
      if (!codeOk) return res.status(400).json({ error: 'Enter a valid code from your authenticator or a backup code.' });
      await db.update(users).set({
        totpSecret: null,
        totpPendingSecret: null,
        totpEnabled: false,
        totpBackupCodes: null,
        updatedAt: new Date(),
      }).where(eq(users.id, userId));
      await writeAudit(req, 'totp_disabled', 'user', userId);
      res.json({ enabled: false });
    } catch (e) {
      console.error('[2fa] disable error:', e);
      res.status(500).json({ error: 'Could not disable 2FA' });
    }
  });

  // ===== KYC =====
  app.post('/api/kyc/submit', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const { personal, identity, strategy } = req.body;

      if (!personal || !identity) {
        return res.status(400).json({ error: 'Personal and identity information are required' });
      }

      const dob = new Date(personal.dob);
      const ageMs = Date.now() - dob.getTime();
      const ageYears = ageMs / (365.25 * 24 * 60 * 60 * 1000);
      const phoneDigits = String(personal.phone || "").replace(/\D/g, "");
      const zipDigits = String(personal.zip || "").replace(/\D/g, "");
      const ssnDigits = String(identity.ssn || "").replace(/\D/g, "");
      const stateCode = String(personal.state || "").trim().toUpperCase();
      const namePattern = /^[A-Za-z][A-Za-z '.-]{1,}$/;

      if (!Number.isFinite(dob.getTime()) || dob.getTime() > Date.now() || ageYears < 18) {
        return res.status(400).json({ error: 'The account holder must be at least 18 years old.' });
      }
      if (!namePattern.test(String(personal.firstName || "").trim()) || !namePattern.test(String(personal.lastName || "").trim())) {
        return res.status(400).json({ error: 'Enter the account holder legal first and last name.' });
      }
      if (!/^[A-Z]{2}$/.test(stateCode)) {
        return res.status(400).json({ error: 'Enter a valid two-letter state.' });
      }
      if (zipDigits.length !== 5) {
        return res.status(400).json({ error: 'Enter a valid 5 digit ZIP code.' });
      }
      if (phoneDigits.length !== 10) {
        return res.status(400).json({ error: 'Enter a valid 10 digit phone number.' });
      }
      if (ssnDigits.length !== 9 || /^(\d)\1{8}$/.test(ssnDigits)) {
        return res.status(400).json({ error: 'Enter a valid 9 digit Social Security Number or ITIN.' });
      }
      if (!['us_citizen', 'permanent_resident'].includes(String(identity.citizenship || ""))) {
        return res.status(400).json({
          error: "Kiddo currently supports US citizens and permanent residents for investing. Join the waitlist for expanded eligibility.",
        });
      }

      let decision = getKycDecision({ personal, identity });

      // No real KYC provider or custodian is wired yet (see
      // CUSTODIAN_SOURCE_OF_TRUTH.md — DriveWealth/Alpaca is a scaffold stub).
      // getKycDecision is a FORMAT check, not an identity check. Auto-"approving"
      // a real user off it — flipping their fund to "active and investing" and
      // telling them "your identity has been verified" — is a false statement of
      // fact and a launch blocker. Fail CLOSED in production for real users:
      // downgrade auto-approve to manual review (gifts still arrive; nothing
      // claims to be verified). Demo walkthroughs and an explicit testing flag
      // keep the auto-approve path so the flow stays walkable.
      if (
        decision.status === "approved" &&
        process.env.NODE_ENV === "production" &&
        process.env.ENABLE_KYC_AUTO_APPROVE !== "1" &&
        !(await isDemoUser(userId))
      ) {
        decision = {
          status: "pending" as const,
          message:
            "Your details look good. Your account needs a quick manual review before investing goes live — gifts can still arrive while we finish.",
          reason: "manual_review_required",
        };
      }

      // Persist the failure reason + message alongside the submitted
      // kycData so the kyc_action_required action item can surface a
      // specific, actionable description (e.g., "The adult opening
      // this fund must be at least 18 years old.") instead of the
      // generic "We weren't able to verify your identity." Cleared
      // on the next successful submission. Per the 2026-05-13 audit:
      // the activity-row description was specific but the action-item
      // card description was generic; this closes that gap.
      const kycData = {
        firstName: String(personal.firstName).trim(),
        lastName: String(personal.lastName).trim(),
        dob: personal.dob,
        address: {
          street: String(personal.street || "").trim(),
          city: String(personal.city || "").trim(),
          state: stateCode,
          zip: zipDigits,
        },
        phone: phoneDigits,
        citizenship: identity.citizenship,
        employment: identity.employment,
        ssnProvided: true,
        lastFailureReason: decision.status === "failed" ? decision.reason : null,
        lastFailureMessage: decision.status === "failed" ? decision.message : null,
      };

      await db.update(users).set({
        kycStatus: decision.status,
        kycSubmittedAt: new Date(),
        kycData: kycData,
        firstName: personal.firstName,
        lastName: personal.lastName,
        updatedAt: new Date(),
      }).where(eq(users.id, userId));

      // Audit trail for SSN/KYC collection (Tier-3 PII). Logs the decision and
      // that an SSN was provided — never the SSN itself. Per
      // policies/data-classification.md (SSN collection is audit-logged).
      await writeAudit(req, 'kyc_submitted', 'user', userId, {
        decision: decision.status,
        ssnProvided: true,
      });

      const userFunds = await storage.getFundsByUser(userId);
      let activatedFunds = 0;
      if (decision.status === 'approved') {
        for (const fund of userFunds) {
          const allowedStrategy = await resolveAllowedFundStrategy(userId, fund.id, strategy);
          if (fund.status === 'draft') {
            await storage.updateFund(fund.id, {
              status: 'active',
              investmentStrategy: allowedStrategy,
            });
            activatedFunds += 1;
          }
        }
      }

      if (decision.status === 'approved') {
        await storage.createActivity({
          userId,
          fundId: userFunds[0]?.id,
          type: 'kyc_approved',
          title: 'Identity verified',
          description: 'Your identity has been verified. Your funds are now active and investing.',
        });
      } else if (decision.status === 'pending') {
        await storage.createActivity({
          userId,
          fundId: userFunds[0]?.id,
          type: 'kyc_pending_review',
          title: 'Identity review in progress',
          description: decision.message,
        });
      } else {
        await storage.createActivity({
          userId,
          fundId: userFunds[0]?.id,
          type: 'kyc_action_required',
          title: 'Identity details need attention',
          description: decision.message,
        });
      }

      await queueMobilePush({
        id: `kyc_status:${decision.status}:${userId}:${new Date().toISOString().slice(0, 16)}`,
        type: `kyc_${decision.status}`,
        userId,
        title:
          decision.status === "approved"
            ? "Your investing account is active"
            : decision.status === "pending"
              ? "Your identity check is in review"
              : "Your identity details need attention",
        body: decision.message,
        deepLink: "/activate",
        metadata: {
          status: decision.status,
          reason: decision.reason,
        },
      });

      res.json({ status: decision.status, activatedFunds, message: decision.message, reason: decision.reason });
    } catch (error) {
      console.error('Error submitting KYC:', error);
      res.status(500).json({ error: 'Failed to submit KYC' });
    }
  });

  app.get('/api/user/kyc-status', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const [user] = await db
        .select({ kycStatus: users.kycStatus, kycSubmittedAt: users.kycSubmittedAt, kycData: users.kycData })
        .from(users)
        .where(eq(users.id, userId));
      const kycStatus = user?.kycStatus || 'none';
      const statusMessage =
        kycStatus === 'approved'
          ? 'Your investing account is active.'
          : kycStatus === 'pending'
            ? 'We are reviewing your identity details now.'
            : kycStatus === 'failed'
              ? 'Your identity details need attention before investing can start.'
              : 'Identity verification has not been completed yet.';
      res.json({
        kycStatus,
        kycSubmittedAt: user?.kycSubmittedAt,
        statusMessage,
        canRetry: kycStatus === 'failed' || kycStatus === 'none',
      });
    } catch (error) {
      console.error('Error fetching KYC status:', error);
      res.status(500).json({ error: 'Failed to fetch KYC status' });
    }
  });

  // ===== PRIVACY =====
  app.patch('/api/funds/:id/privacy', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const fund = await storage.getFund(req.params.id);
      if (!fund) return res.status(404).json({ error: 'Fund not found' });
      if (req.fundAccessRole !== 'owner') return res.status(403).json({ error: 'Forbidden' });

      const { isDiscoverable } = req.body;
      const isUtmaFund = String(fund.accountType || "").toUpperCase() === "UTMA" || !fund.accountType;
      if (isUtmaFund) {
        const updated = await storage.updateFund(req.params.id, { isDiscoverable: false });
        return res.json({
          ...updated,
          forcedPrivate: true,
          note: "UTMA funds are always private and accessible by direct link only.",
        });
      }
      const updated = await storage.updateFund(req.params.id, { isDiscoverable: !!isDiscoverable });
      res.json(updated);
    } catch (error) {
      console.error('Error updating privacy:', error);
      res.status(500).json({ error: 'Failed to update privacy' });
    }
  });

  // Memory Book moderation toggle (per-fund). Default off everywhere.
  // When on, gifter-submitted entries land as 'pending_review' and the
  // parent gets a tray to approve or delete. The toggle is exposed in
  // the Memory Book settings UI; this is the server side. Audit-logged
  // because flipping the toggle is a meaningful product policy change
  // for the fund.
  app.patch('/api/funds/:id/memory-moderation', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const fund = await storage.getFund(req.params.id);
      if (!fund) return res.status(404).json({ error: 'Fund not found' });
      if (req.fundAccessRole !== 'owner') return res.status(403).json({ error: 'Forbidden' });

      const enabled = !!req.body?.enabled;
      const updated = await storage.updateFund(req.params.id, { gifterMemoryModeration: enabled });
      try {
        await writeAudit(req, 'memory_moderation_toggled', 'fund', fund.id, { enabled });
      } catch {
        // best-effort audit
      }
      res.json(updated);
    } catch (error) {
      console.error('Error updating memory moderation:', error);
      res.status(500).json({ error: 'Failed to update memory moderation setting' });
    }
  });

  // ===== SELL HOLDINGS =====
  app.post('/api/holdings/sell', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const { holdingId, fundId, shares, confirmTaxExplainer } = req.body;

      if (!holdingId || !fundId) {
        return res.status(400).json({ error: 'holdingId and fundId are required' });
      }

      const fund = await storage.getFund(fundId);
      if (!fund) return res.status(404).json({ error: 'Fund not found' });
      // Owner-only. This route is NOT under /api/funds/:fundId, so
      // requireOwnedFundParam never runs and req.fundAccessRole is undefined
      // here — the old `fundAccessRole !== 'owner'` check therefore 403'd every
      // caller, including the owner (selling was broken). Verify ownership
      // directly off the body-supplied fundId.
      if (fund.userId !== userId) return res.status(403).json({ error: 'Forbidden' });

      const holdingsList = await storage.getHoldingsByFund(fundId);
      const holding = holdingsList.find(h => h.id === holdingId);
      if (!holding) return res.status(404).json({ error: 'Holding not found' });

      const requestedShares = shares ? parseFloat(shares) : parseFloat(holding.shares);
      const currentShares = parseFloat(holding.shares);
      // If requested shares are within rounding epsilon of total, treat as full sell
      const sharesToSell = Math.abs(requestedShares - currentShares) < 0.001 ? currentShares : requestedShares;
      if (sharesToSell <= 0 || sharesToSell > currentShares + 0.001) {
        return res.status(400).json({ error: 'Invalid number of shares' });
      }

      const currentValue = parseFloat(holding.currentValue);
      if (!Number.isFinite(currentShares) || currentShares <= 0) {
        return res.status(400).json({ error: 'Holding has no sellable shares' });
      }
      if (!Number.isFinite(currentValue) || currentValue <= 0) {
        return res.status(400).json({ error: 'Holding value is unavailable. Try refreshing prices and retry.' });
      }

      const pricePerShare = currentValue / currentShares;
      const saleValue = Math.min(sharesToSell, currentShares) * pricePerShare;
      if (!Number.isFinite(saleValue) || saleValue <= 0) {
        return res.status(400).json({ error: 'Could not calculate sale value' });
      }
      const remainingShares = currentShares - sharesToSell;

      // Realized-gain math, computed BEFORE the holding is updated /
      // deleted so the original cost basis is still readable.
      //
      // costBasisSold = (totalCostBasis / totalShares) * sharesSold
      //   — average-cost method, matching the basis tracking we use
      //   throughout the rest of the app. No per-lot FIFO/LIFO
      //   today; would need a sales-lots table.
      // realizedGain = saleValue - costBasisSold (signed; loss is
      //   negative).
      // holdingPeriod = 'long_term' if the EARLIEST settled gift
      //   funding this ticker invested >365 days ago; otherwise
      //   'short_term'. Conservative: a partial sell that includes
      //   newer shares would technically be short-term for those,
      //   but average-cost basis blurs that distinction by design.
      const totalCostBasis = parseFloat(holding.costBasis);
      const costBasisSold = Number.isFinite(totalCostBasis) && currentShares > 0
        ? (totalCostBasis / currentShares) * sharesToSell
        : 0;
      const realizedGain = saleValue - costBasisSold;

      // Earliest-purchase lookup for holding-period classification.
      // gift_allocations joins to gifts.invested_at for the canonical
      // "when did money for this ticker first land in real shares"
      // timestamp. Falls back to long_term if no allocation row
      // exists (legacy data) — the conservative choice biases toward
      // long-term-cap-gains treatment which favors the taxpayer.
      let holdingPeriod: 'short_term' | 'long_term' = 'long_term';
      try {
        const earliest = await db.execute(sql`
          SELECT MIN(g.invested_at) AS earliest
          FROM gift_allocations ga
          JOIN gifts g ON g.id = ga.gift_id
          WHERE ga.fund_id = ${fundId}
            AND ga.ticker = ${holding.ticker}
            AND g.invested_at IS NOT NULL
        `);
        const earliestRow = (earliest.rows as any[])?.[0];
        if (earliestRow?.earliest) {
          const earliestMs = new Date(earliestRow.earliest).getTime();
          const oneYearAgo = Date.now() - 365 * 24 * 60 * 60 * 1000;
          holdingPeriod = earliestMs < oneYearAgo ? 'long_term' : 'short_term';
        }
      } catch (err) {
        // Non-fatal — defaults to long_term (taxpayer-favorable).
        console.warn('[sell] holding-period lookup failed, defaulting to long_term:', (err as any)?.message || err);
      }

      // First-sell tax explainer gate. Per AGE_18_HANDOFF_SPEC.md
      // bucket 2. Fires once for a kid-owner: their first sale comes
      // with a forced read of "here's the realized gain, here's roughly
      // what you'll owe in tax." Subsequent sells skip the auto-popup
      // (the kid is now informed). The explainer is also reachable
      // from Settings for refreshers.
      //
      // The client surfaces the 409 as a modal, then re-fires with
      // confirmTaxExplainer:true. Server stamps users.firstSellCompletedAt
      // in the success path below so the gate doesn't re-fire even if
      // the kid sells immediately after confirming the first time.
      const isKidOwner =
        String((fund as any).accountType || "").toLowerCase() === "personal" &&
        String((fund as any).recipientRelation || "").toLowerCase() === "self";
      let kidOwnerNeedsExplainer = false;
      let kidOwnerBracket: string | null = null;
      if (isKidOwner) {
        const [userRow] = await db
          .select({
            firstSellCompletedAt: users.firstSellCompletedAt,
            estimatedIncomeBracket: users.estimatedIncomeBracket,
          })
          .from(users)
          .where(eq(users.id, userId))
          .limit(1);
        kidOwnerBracket = (userRow?.estimatedIncomeBracket as string) || null;
        if (!userRow?.firstSellCompletedAt && !confirmTaxExplainer) {
          kidOwnerNeedsExplainer = true;
        }
      }
      if (kidOwnerNeedsExplainer) {
        // LTCG federal rate buckets. Approximations of 2026 brackets
        // and intentionally conservative — over-estimating slightly is
        // friendlier than under-estimating. State tax is NOT included
        // (varies widely). The modal copy says "federal only, your
        // state may add more."
        const longTermRate =
          kidOwnerBracket === "100_plus" ? 0.20
            : kidOwnerBracket === "45_100" ? 0.15
            : kidOwnerBracket === "0_45" ? 0.00
            : 0.15; // unknown bracket → safe middle estimate
        // Short-term gains are taxed at ordinary income rates. Use a
        // bracket-aware approximation: 10% / 22% / 32% for the same
        // three buckets. Again conservative-friendly.
        const shortTermRate =
          kidOwnerBracket === "100_plus" ? 0.32
            : kidOwnerBracket === "45_100" ? 0.22
            : kidOwnerBracket === "0_45" ? 0.10
            : 0.22;
        const taxRate = holdingPeriod === "long_term" ? longTermRate : shortTermRate;
        const estimatedTax = Math.max(0, realizedGain) * taxRate;
        return res.status(409).json({
          error: "first_sell_tax_explainer_required",
          ticker: holding.ticker,
          sharesToSell: sharesToSell.toFixed(6),
          saleValue: saleValue.toFixed(2),
          costBasisSold: costBasisSold.toFixed(2),
          realizedGain: realizedGain.toFixed(2),
          holdingPeriod,
          estimatedTax: estimatedTax.toFixed(2),
          estimatedTaxRate: taxRate,
          incomeBracket: kidOwnerBracket,
          message: "First sale. Here's what the IRS sees, in plain English.",
        });
      }

      if (remainingShares <= 0.0001) {
        await storage.deleteHolding(holdingId);
        // Holding is gone. Drop its allocation rows so per-gift attribution doesn't
        // point at a ticker that no longer exists in this fund.
        await storage.deleteGiftAllocationsByFundAndTicker(fundId, holding.ticker);
      } else {
        const remainingCostBasis = (parseFloat(holding.costBasis) / parseFloat(holding.shares)) * remainingShares;
        const remainingValue = pricePerShare * remainingShares;
        await storage.updateHolding(holdingId, {
          shares: remainingShares.toFixed(6),
          costBasis: remainingCostBasis.toFixed(2),
          currentValue: remainingValue.toFixed(2),
          gain: (remainingValue - remainingCostBasis).toFixed(2),
        });
        // Partial sell: scale every allocation row for this ticker by the remaining fraction
        // (e.g. selling half of AAPL halves every Apple allocation's cost_basis and shares).
        const remainingFraction = currentShares > 0 ? remainingShares / currentShares : 0;
        await storage.scaleGiftAllocationsByFundAndTicker(fundId, holding.ticker, remainingFraction);
      }

      const newBalance = parseFloat(fund.balance) - saleValue;
      const newCash = parseFloat(String((fund as any).cashBalance || "0")) + saleValue;
      await storage.updateFund(fundId, {
        balance: Math.max(0, newBalance).toFixed(2),
        cashBalance: newCash.toFixed(2),
      } as any);

      await storage.createActivity({
        userId,
        fundId,
        type: 'sell',
        title: `${holding.ticker} moved to cash`,
        description: `${sharesToSell.toFixed(4)} shares of ${holding.name} moved to cash for $${saleValue.toFixed(2)}. Cash will settle in 1 to 2 business days.`,
        amount: saleValue.toFixed(2),
        // Mutation-clarity metadata — Activity's expanded "What moved"
        // panel reads ticker + shares from here so it can render the
        // canonical before → after pill flow ("0.5 GOOGL → Cash · $172.50")
        // instead of falling back to the title-only form ("GOOGL → Cash").
        // Also includes holdingId for any future per-holding deep-linking.
        metadata: JSON.stringify({
          ticker: holding.ticker,
          shares: sharesToSell.toFixed(4),
          holdingId: holding.id,
          holdingName: holding.name,
        }),
      });

      await storage.createTransaction({
        userId,
        type: 'sell',
        amount: saleValue.toFixed(2),
        status: 'completed',
        description: `Moved ${sharesToSell.toFixed(4)} shares of ${holding.ticker} to cash`,
        fundId,
        completedAt: new Date(),
        // Tax-reporting triplet (migration 0013). costBasisSold +
        // realizedGain enable the Tax Documents "Realized sales this
        // year" section. holdingPeriod drives the short-term vs
        // long-term tax-treatment label. See
        // project_realized_gain_architecture for the full picture.
        realizedGain: realizedGain.toFixed(2),
        costBasisSold: costBasisSold.toFixed(2),
        holdingPeriod,
      } as any);

      await captureFundSnapshot(fundId);

      // Stamp first-sell completion for kid-owners so the tax explainer
      // doesn't re-fire on their next sale. Best-effort; not blocking
      // the response — if the update fails (e.g. transient DB blip)
      // the kid sees the explainer again next time, which is the
      // taxpayer-friendly failure mode.
      if (isKidOwner) {
        try {
          await db.update(users)
            .set({ firstSellCompletedAt: new Date(), updatedAt: new Date() })
            .where(and(eq(users.id, userId), sql`${users.firstSellCompletedAt} IS NULL`));
        } catch (err) {
          console.warn('[sell] firstSellCompletedAt stamp failed:', (err as any)?.message || err);
        }
      }

      res.json({
        success: true,
        saleValue: saleValue.toFixed(2),
        ticker: holding.ticker,
        sharesSold: sharesToSell,
        // Hand back the tax triplet so the client can show a
        // friendly "You realized $X.XX in gains" confirmation
        // toast right after the sell completes — without making
        // the user navigate to Tax Documents to verify.
        realizedGain: realizedGain.toFixed(2),
        costBasisSold: costBasisSold.toFixed(2),
        holdingPeriod,
      });
    } catch (error) {
      console.error('Error selling holding:', error);
      const message = error instanceof Error ? error.message : 'Failed to sell holding';
      res.status(500).json({ error: message });
    }
  });

  // ===== WITHDRAWALS =====
  app.post('/api/withdrawals', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const { fundId, amount, bankAccountId } = req.body;

      if (!fundId || !amount || !bankAccountId) {
        return res.status(400).json({ error: 'fundId, amount, and bankAccountId are required' });
      }

      // Demo-fund sandbox. Per DUNPHY_DEMO_SPEC.md Phase 2 + server/demoSandbox.ts.
      // No custodian webhook, no balance mutation, no activity row — just a clean
      // "looks like it worked" response so the demo visitor sees the success state.
      if (await isDemoFund(fundId)) {
        const withdrawAmount = parseFloat(String(amount));
        return res.json({
          success: true,
          isDemo: true,
          amount: Number.isFinite(withdrawAmount) ? withdrawAmount.toFixed(2) : "0.00",
          delivered: true,
          achLive: false,
          message: "Demo mode. No real funds moved.",
        });
      }

      const fund = await storage.getFund(fundId);
      if (!fund) return res.status(404).json({ error: 'Fund not found' });
      // Owner-only. Bare path (not under /api/funds/:fundId) → req.fundAccessRole
      // is undefined here; the old check 403'd every caller, breaking
      // withdrawals. Verify ownership directly off the body-supplied fundId.
      if (fund.userId !== userId) return res.status(403).json({ error: 'Forbidden' });

      const bankAccounts = await storage.getBankAccountsByUser(userId);
      const bankAccount = bankAccounts.find(b => b.id === bankAccountId);
      if (!bankAccount) return res.status(404).json({ error: 'Bank account not found' });

      // Withdrawal source is settled cash held in the fund's brokerage cash sleeve,
      // i.e. cashBalance — money from sold holdings + uninvested gifts.
      // pendingBalance is for in-flight gifts that haven't completed settlement yet
      // and is NOT eligible for withdrawal.
      const withdrawAmount = parseFloat(amount);
      const availableCash = parseFloat(String((fund as any).cashBalance || "0"));
      if (!Number.isFinite(withdrawAmount) || withdrawAmount <= 0) {
        return res.status(400).json({ error: 'Withdrawal amount must be greater than zero' });
      }
      if (withdrawAmount > availableCash + 0.001) {
        return res.status(400).json({ error: `Insufficient cash. Available: $${availableCash.toFixed(2)}` });
      }

      // First-large-withdrawal cooldown for kid-owners post-handoff.
      // Per AGE_18_HANDOFF_SPEC.md bucket 2. Kicks in when:
      //   1. User is the kid-owner (accountType=Personal + relation=self)
      //   2. firstLargeWithdrawalAt is null (no prior gated big withdrawal)
      //   3. Amount > 25% of fund balance OR > $2,000 (whichever lower)
      // Two-step UX:
      //   - First qualifying attempt: server stamps cooldownStartedAt
      //     and returns 409. Client shows the modal and waits.
      //   - After 24h: same request goes through, stamps
      //     firstLargeWithdrawalAt, and all future withdrawals on this
      //     fund bypass the cooldown.
      // Sub-threshold withdrawals do NOT stamp firstLargeWithdrawalAt —
      // otherwise a kid could bypass the gate by doing a $5 dummy
      // withdrawal first.
      const isKidOwner =
        String((fund as any).accountType || "").toLowerCase() === "personal" &&
        String((fund as any).recipientRelation || "").toLowerCase() === "self";
      const investedBalance = parseFloat(String((fund as any).balance || "0"));
      const fundTotal = investedBalance + availableCash;
      const threshold = Math.min(fundTotal * 0.25, 2000);
      const isLargeWithdrawal = isKidOwner && fundTotal > 0 && withdrawAmount > threshold;
      const cooldownStamped = Boolean((fund as any).firstLargeWithdrawalAt);
      const COOLDOWN_MS = 24 * 60 * 60 * 1000;

      if (isLargeWithdrawal && !cooldownStamped) {
        const cooldownStart = (fund as any).firstLargeWithdrawalCooldownStartedAt;
        if (!cooldownStart) {
          await storage.updateFund(fundId, {
            firstLargeWithdrawalCooldownStartedAt: new Date(),
          } as any);
          return res.status(409).json({
            error: "first_withdrawal_cooldown",
            cooldownHours: 24,
            cooldownStartedAt: new Date().toISOString(),
            cooldownEndsAt: new Date(Date.now() + COOLDOWN_MS).toISOString(),
            message: "First big withdrawal. We hold for 24 hours so you can sleep on it.",
          });
        }
        const elapsed = Date.now() - new Date(cooldownStart).getTime();
        if (elapsed < COOLDOWN_MS) {
          return res.status(409).json({
            error: "first_withdrawal_cooldown",
            cooldownHours: 24,
            cooldownStartedAt: new Date(cooldownStart).toISOString(),
            cooldownEndsAt: new Date(new Date(cooldownStart).getTime() + COOLDOWN_MS).toISOString(),
            message: "The 24-hour wait isn't over yet. We'll let it through automatically once it is.",
          });
        }
        // Cooldown elapsed — fall through and stamp the completion.
      }

      await storage.updateFund(fundId, {
        cashBalance: Math.max(0, availableCash - withdrawAmount).toFixed(2),
        // Only stamp on a LARGE withdrawal that satisfied the cooldown.
        // Sub-threshold withdrawals leave the flag alone so a later
        // large withdrawal still goes through the gate.
        ...(isLargeWithdrawal && !cooldownStamped
          ? { firstLargeWithdrawalAt: new Date() }
          : {}),
      } as any);

      // Fire the custodian webhook to actually move money out. If no webhook is configured,
      // queueCustodianTransfer falls back to writing to the local outbox so ops can process
      // manually — and we mark the transaction so the UI is honest about it.
      const achLive = isCustodianAchEnabled();
      const transferResult = await queueCustodianTransfer({
        type: "withdrawal_requested",
        fundId,
        requestedByUserId: userId,
        requestedAt: new Date().toISOString(),
        amount: withdrawAmount.toFixed(2),
        currency: "USD",
        bankAccountId,
        bankName: bankAccount.bankName,
        bankLast4: bankAccount.accountLast4,
      });

      const delivered = transferResult.delivered;
      const transactionStatus = delivered ? 'processing' : 'pending_manual_processing';
      const activityDescription = delivered
        ? `$${withdrawAmount.toFixed(2)} sent to ${bankAccount.bankName} ending in ${bankAccount.accountLast4}. Expect 1 to 3 business days.`
        : `$${withdrawAmount.toFixed(2)} queued for ${bankAccount.bankName} ending in ${bankAccount.accountLast4}. Our team will complete the transfer manually during early access.`;

      await storage.createActivity({
        userId,
        fundId,
        type: 'withdrawal',
        title: delivered ? 'Cash sent to bank' : 'Withdrawal queued',
        description: activityDescription,
        amount: withdrawAmount.toFixed(2),
        // Status in metadata so the Activity Pending tab can pick this up.
        // Activities table has no status column, but the GET /api/activities
        // enrichment falls back to metadata.status when there's no linked
        // gift status — that's what surfaces this to the Pending tab.
        metadata: JSON.stringify({
          status: delivered ? 'completed' : 'pending',
          bankName: bankAccount.bankName,
          bankLast4: bankAccount.accountLast4,
          delivered,
        }),
      });

      await storage.createTransaction({
        userId,
        type: 'withdrawal',
        amount: withdrawAmount.toFixed(2),
        status: transactionStatus,
        description: `${delivered ? 'Cash sent to' : 'Cash queued for'} ${bankAccount.bankName} ending in ${bankAccount.accountLast4}`,
        fundId,
      });

      // Audit trail for money LEAVING a child's custodial account — the most
      // sensitive money operation in the app. Logs the fact + amount + bank
      // last-4 + delivery state; never the full account number. Per
      // policies/data-classification.md (sensitive operations are audit-logged).
      await writeAudit(req, 'fund_withdrawal', 'fund', fundId, {
        amount: withdrawAmount.toFixed(2),
        bankLast4: bankAccount.accountLast4,
        delivered,
        status: transactionStatus,
      });

      await captureFundSnapshot(fundId);

      res.json({
        success: true,
        amount: withdrawAmount.toFixed(2),
        delivered,
        achLive,
        bankAccount: { bankName: bankAccount.bankName, last4: bankAccount.accountLast4 },
      });
    } catch (error) {
      console.error('Error processing withdrawal:', error);
      res.status(500).json({ error: 'Failed to process withdrawal' });
    }
  });

  // Liquidate ALL holdings in a fund in one shot. Optionally chain a withdrawal
  // of the entire resulting cash balance to a linked bank account.
  // Body: { bankAccountId?: string }  // when provided, sweeps cash to bank after liquidation
  // Close-fund endpoint. Designed against
  // project_cancellation_dark_pattern_avoidance.md and
  // project_close_fund_design_lens.md (locked memory).
  //
  // What this DOES:
  //   - Sets fund.status = 'closed' (reversible — see /reopen below)
  //   - Cancels every active recurring contribution on this fund
  //   - Writes an audit log entry + an activity row for the parent's history
  //   - Records the optional reason (UX collects it; not required to close)
  //
  // What this does NOT do (deliberate):
  //   - Does NOT delete the fund. The schema row stays, the audit log stays,
  //     the Memory Book stays. Per the kid-at-18 lens — Memory Book is the
  //     artifact, never deleted by a parent action.
  //   - Does NOT auto-withdraw cash. That's a separate, explicit decision
  //     via the existing /api/funds/:id/liquidate flow. Parents who want to
  //     close AND withdraw must do both deliberately.
  //   - Does NOT cancel the parent's Kiddo+ / Family subscription. Closing
  //     one fund doesn't end the parent's plan; that's what
  //     /api/subscription/cancel is for.
  //   - Does NOT block reopening. Anti-dark-pattern: a parent who closes
  //     and changes their mind can reopen the same row. No re-onboarding.
  app.post('/api/funds/:id/close', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const fundId = req.params.id;
      const fund = await storage.getFund(fundId);
      if (!fund) return res.status(404).json({ error: 'Fund not found' });
      if (req.fundAccessRole !== 'owner') return res.status(403).json({ error: 'Forbidden' });
      if (String(fund.status || '').toLowerCase() === 'closed') {
        return res.json({ ok: true, alreadyClosed: true });
      }

      // Optional reason from the client. Stored in the audit metadata for
      // future product analysis; never a gate to closing.
      const reason = String(req.body?.reason || '').slice(0, 200).trim() || null;

      // Cancel every active recurring contribution for this fund. Same
      // pattern the existing DELETE /api/parent-contributions/:id route
      // uses, just looped over the active set.
      const contributions = await storage.getParentContributionsByFund(fundId);
      const activeContribs = contributions.filter((c) => String(c.status || '').toLowerCase() === 'active');
      let canceledContribCount = 0;
      for (const contrib of activeContribs) {
        try {
          await storage.deleteParentContribution(contrib.id);
          canceledContribCount += 1;
        } catch (err) {
          console.warn('[close-fund] failed to cancel recurring', contrib.id, err);
        }
      }

      // Revoke all collaborator access on close. The fund's data
      // stays — Memory Book + activity + cash + audit trail — but the
      // co-parent/viewer access list does not survive a closure. If
      // the parent reopens, they'll need to re-invite anyone they want
      // back in. This matches the kid-at-18 lens: closure is a
      // reset to the owner's solo control, just like the age-18
      // handoff resets to the kid's solo control.
      let revokedCollaboratorCount = 0;
      try {
        revokedCollaboratorCount = await storage.deleteCollaboratorsByFund(fundId);
      } catch (err) {
        console.warn('[close-fund] failed to revoke collaborators:', err);
      }

      // Mark closed.
      await storage.updateFund(fundId, { status: 'closed' } as any);

      // Activity row — parent will see this in History when they reopen
      // the fund or browse its archive. Same pattern the cancel-subscription
      // flow uses (logMonetizationActivity at line 9752 etc.).
      try {
        await storage.createActivity({
          userId,
          fundId,
          type: 'fund_closed',
          title: `${fund.recipientFirstName ? `${fund.recipientFirstName}'s` : 'This'} fund was closed`,
          description: [
            canceledContribCount > 0 ? `Recurring investments canceled (${canceledContribCount}).` : null,
            revokedCollaboratorCount > 0 ? `Co-parent access revoked (${revokedCollaboratorCount}).` : null,
            'Memory Book and history preserved. Reopen anytime from Settings.',
          ].filter(Boolean).join(' '),
          metadata: JSON.stringify({ reason, canceledContribCount, revokedCollaboratorCount }),
        });
      } catch (err) {
        console.warn('[close-fund] activity write failed:', err);
      }

      // Audit log — independent of activity feed; for compliance trail.
      try {
        await db.insert(auditLogs).values({
          userId,
          action: 'fund_closed',
          resourceType: 'fund',
          resourceId: fundId,
          metadata: JSON.stringify({ reason, canceledContribCount }),
          ipAddress: req.ip || (req.socket as any)?.remoteAddress || null,
          userAgent: req.get('user-agent') || null,
        });
      } catch (err) {
        console.warn('[close-fund] audit write failed:', err);
      }

      // First-party analytics so we can see the close funnel and detect
      // any drift toward "more closes than expected."
      recordEvent({
        ...eventCtxFromReq(req),
        name: 'fund_closed',
        userId,
        fundId,
        source: 'web',
        props: { reason, canceledContribCount, hadActiveContribs: activeContribs.length > 0 },
      });

      res.json({ ok: true, canceledContribCount });
    } catch (error) {
      console.error('Error closing fund:', error);
      res.status(500).json({ error: 'Failed to close fund' });
    }
  });

  // Hard-delete a NEVER-FUNDED fund. Distinct from close (which pauses and
  // preserves): this removes the fund + all its rows entirely. Allowed ONLY
  // when the fund never held money — zero balance/cash/pending, no holdings,
  // no gifts — i.e. an abandoned draft or a test fund. A fund that ever
  // received a gift or held a position carries a beneficiary's contribution
  // record + (eventually) tax history, so it can only be CLOSED, never
  // deleted; we point those at the close flow. Owner-only (the legal
  // custodian, not a co-admin) — deletion is more destructive than any
  // mutation, so we require the literal fund.userId match, not just the
  // 'owner' access role.
  app.post('/api/funds/:id/delete', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const fundId = req.params.id;
      const fund = await storage.getFund(fundId);
      if (!fund) return res.status(404).json({ error: 'Fund not found' });
      // Strict ownership: only the custodian who owns the fund can delete it.
      if (fund.userId !== userId) return res.status(403).json({ error: 'Forbidden' });

      // Eligibility: the fund must never have held money. Any non-zero
      // balance slice, any holding, or any gift blocks deletion and routes
      // the user to close instead.
      const bal = parseFloat(String(fund.balance || '0'));
      const cash = parseFloat(String((fund as any).cashBalance || '0'));
      const pending = parseFloat(String(fund.pendingBalance || '0'));
      const holdingsForFund = await storage.getHoldingsByFund(fundId);
      const giftsForFund = await storage.getGiftsByFund(fundId);
      const blockers: string[] = [];
      if (bal > 0.005 || cash > 0.005 || pending > 0.005) blockers.push('it holds a balance');
      if (holdingsForFund.length > 0) blockers.push('it has investment holdings');
      if (giftsForFund.length > 0) blockers.push(`it has received ${giftsForFund.length} gift${giftsForFund.length === 1 ? '' : 's'}`);

      // ── Stripe / billing safety ──────────────────────────────────────
      // The cascade deletes fund-scoped rows that can carry a LIVE recurring
      // Stripe subscription — fund_memberships (the per-fund Plus/Family sub)
      // and recurring_gifts (a gifter's auto-charge) — plus sponsored subs.
      // Deleting those DB rows without cancelling in Stripe would orphan the
      // subscription: the card keeps getting billed with no record on our
      // side. A $0 balance does NOT imply no billing, so we must check it
      // explicitly. We BLOCK (rather than auto-cancel) — consistent with the
      // rest of this gate — and route the user to cancel/close first, where
      // the existing Stripe-cancel paths run. (subscriptions is user-scoped,
      // never fund-deleted, so it's intentionally not checked here.)
      let billing = { memberships: 0, recurring: 0, sponsorships: 0 };
      try {
        const r = await db.execute(sql`
          SELECT
            (SELECT count(*) FROM fund_memberships WHERE fund_id = ${fundId} AND status = 'active')::int AS memberships,
            (SELECT count(*) FROM recurring_gifts WHERE fund_id = ${fundId} AND status = 'active')::int AS recurring,
            (SELECT count(*) FROM sponsored_subscriptions WHERE fund_id = ${fundId} AND status = 'active' AND expires_at > now())::int AS sponsorships
        `);
        const row: any = (r.rows as any[])[0] || {};
        billing = { memberships: Number(row.memberships || 0), recurring: Number(row.recurring || 0), sponsorships: Number(row.sponsorships || 0) };
      } catch (err) {
        // Fail CLOSED: if we can't confirm there's no live billing, refuse to
        // delete rather than risk orphaning a Stripe subscription.
        console.warn('[delete-fund] billing check failed — blocking delete:', err);
        return res.status(409).json({
          error: 'fund_not_deletable',
          message: "We couldn't verify this fund has no active subscription, so we didn't delete it. Try again, or close the fund instead.",
        });
      }
      if (billing.memberships > 0) blockers.push('it has an active subscription');
      if (billing.recurring > 0) blockers.push('it has an active recurring gift');
      if (billing.sponsorships > 0) blockers.push('it has a sponsored subscription');

      if (blockers.length > 0) {
        const hasBilling = billing.memberships > 0 || billing.recurring > 0 || billing.sponsorships > 0;
        return res.status(409).json({
          error: 'fund_not_deletable',
          message: `This fund can't be deleted because ${blockers.join(' and ')}. ${
            hasBilling
              ? 'Cancel the active subscription first, then close the fund — closing preserves the Memory Book and records while pausing the gift link.'
              : 'Close it instead — that preserves the Memory Book and records while pausing the gift link.'
          }`,
          blockers,
        });
      }

      await storage.deleteFundCascade(fundId);

      // Best-effort orphan sweep. Non-fatal: the fund is already gone from the
      // DB, so a failure here just leaves a harmless file/JSON leftover — it
      // must never turn a successful delete into a 500.
      // 1) The fund's uploaded child-photo directory (uploads/child-photos/<id>).
      try {
        const safeFundId = String(fundId).replace(/[^a-zA-Z0-9_-]/g, "");
        if (safeFundId) {
          await fs.rm(path.resolve(process.cwd(), "uploads", "child-photos", safeFundId), { recursive: true, force: true });
        }
      } catch (err) {
        console.warn('[delete-fund] child-photo cleanup failed:', err);
      }
      // 2) The fund's entries in the file-based gifter-notification store.
      //    Almost always empty for a never-funded fund (no gifts → no
      //    followers), but swept so nothing lingers keyed to a dead fund id.
      try {
        const store: any = await loadGifterNotificationStore();
        let changed = false;
        if (store?.subscribersByFund?.[fundId]) { delete store.subscribersByFund[fundId]; changed = true; }
        if (store?.settingsByFund?.[fundId]) { delete store.settingsByFund[fundId]; changed = true; }
        if (store?.memorySharesByToken) {
          for (const token of Object.keys(store.memorySharesByToken)) {
            if (String(store.memorySharesByToken[token]?.fundId) === fundId) { delete store.memorySharesByToken[token]; changed = true; }
          }
        }
        if (changed) await saveGifterNotificationStore(store);
      } catch (err) {
        console.warn('[delete-fund] gifter-notification cleanup failed:', err);
      }

      // Audit row (NOT fund-scoped — auditLogs survives the fund) for the
      // compliance trail. Same shape as the close-fund audit write above.
      try {
        await db.insert(auditLogs).values({
          userId,
          action: 'fund_deleted',
          resourceType: 'fund',
          resourceId: fundId,
          metadata: JSON.stringify({
            recipientFirstName: fund.recipientFirstName || null,
            status: fund.status || null,
            reason: String(req.body?.reason || '').slice(0, 200).trim() || null,
          }),
          ipAddress: req.ip || (req.socket as any)?.remoteAddress || null,
          userAgent: req.get('user-agent') || null,
        });
      } catch (err) {
        console.warn('[delete-fund] audit write failed:', err);
      }

      recordEvent({
        ...eventCtxFromReq(req),
        name: 'fund_deleted',
        userId,
        fundId,
        source: 'web',
        props: { status: fund.status || null },
      });

      res.json({ ok: true });
    } catch (error) {
      console.error('Error deleting fund:', error);
      res.status(500).json({ error: 'Failed to delete fund' });
    }
  });

  // Reopen a previously-closed fund. Anti-dark-pattern: closing is
  // reversible. The Memory Book and audit log are intact; recurring
  // contributions were canceled at close-time and must be set up again
  // by the parent (we deliberately don't auto-restore them — life
  // changes happen between close and reopen, the parent should choose
  // their amount fresh).
  app.post('/api/funds/:id/reopen', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const fundId = req.params.id;
      const fund = await storage.getFund(fundId);
      if (!fund) return res.status(404).json({ error: 'Fund not found' });
      if (req.fundAccessRole !== 'owner') return res.status(403).json({ error: 'Forbidden' });
      const currentStatus = String(fund.status || '').toLowerCase();
      if (currentStatus !== 'closed') {
        return res.status(400).json({ error: 'Fund is not closed' });
      }

      await storage.updateFund(fundId, { status: 'active' } as any);

      try {
        await storage.createActivity({
          userId,
          fundId,
          type: 'fund_reopened',
          title: `${fund.recipientFirstName ? `${fund.recipientFirstName}'s` : 'This'} fund was reopened`,
          description: 'Welcome back. The gift link is live again. Set up new recurring investments any time.',
          metadata: null,
        });
      } catch (err) {
        console.warn('[reopen-fund] activity write failed:', err);
      }

      try {
        await db.insert(auditLogs).values({
          userId,
          action: 'fund_reopened',
          resourceType: 'fund',
          resourceId: fundId,
          metadata: null,
          ipAddress: req.ip || (req.socket as any)?.remoteAddress || null,
          userAgent: req.get('user-agent') || null,
        });
      } catch (err) {
        console.warn('[reopen-fund] audit write failed:', err);
      }

      recordEvent({
        ...eventCtxFromReq(req),
        name: 'fund_reopened',
        userId,
        fundId,
        source: 'web',
      });

      res.json({ ok: true });
    } catch (error) {
      console.error('Error reopening fund:', error);
      res.status(500).json({ error: 'Failed to reopen fund' });
    }
  });

  app.post('/api/funds/:id/liquidate', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const fundId = req.params.id;
      const { bankAccountId } = req.body || {};

      const fund = await storage.getFund(fundId);
      if (!fund) return res.status(404).json({ error: 'Fund not found' });
      if (req.fundAccessRole !== 'owner') return res.status(403).json({ error: 'Forbidden' });

      // If a bank is requested for the chained withdrawal, validate it up front so we
      // don't liquidate and then fail at the last step.
      let bankAccount: any = null;
      if (bankAccountId) {
        const bankAccounts = await storage.getBankAccountsByUser(userId);
        bankAccount = bankAccounts.find(b => b.id === bankAccountId);
        if (!bankAccount) return res.status(404).json({ error: 'Bank account not found' });
      }

      const holdingsList = await storage.getHoldingsByFund(fundId);
      if (holdingsList.length === 0 && parseFloat(String((fund as any).cashBalance || "0")) <= 0) {
        return res.status(400).json({ error: 'Nothing to liquidate' });
      }

      // Sell every holding fully. Mirrors the per-holding sell logic but without per-call HTTP overhead.
      const sales: Array<{ ticker: string; saleValue: number; sharesSold: number }> = [];
      let totalSaleValue = 0;
      for (const holding of holdingsList) {
        const currentShares = parseFloat(holding.shares);
        const currentValue = parseFloat(holding.currentValue);
        if (!Number.isFinite(currentShares) || currentShares <= 0) continue;
        if (!Number.isFinite(currentValue) || currentValue <= 0) continue;
        const pricePerShare = currentValue / currentShares;
        const saleValue = currentShares * pricePerShare;
        await storage.deleteHolding(holding.id);
        // Holding is gone — drop its per-gift allocation rows. The originating gifts
        // remain in the gifts table; their allocation history just no longer points at
        // a ticker since this fund has fully exited it.
        await storage.deleteGiftAllocationsByFundAndTicker(fundId, holding.ticker);
        await storage.createTransaction({
          userId,
          type: 'sell',
          amount: saleValue.toFixed(2),
          status: 'completed',
          description: `Liquidated ${currentShares.toFixed(4)} shares of ${holding.ticker}`,
          fundId,
          completedAt: new Date(),
        });
        sales.push({ ticker: holding.ticker, saleValue, sharesSold: currentShares });
        totalSaleValue += saleValue;
      }

      const previousBalance = parseFloat(fund.balance || "0");
      const previousCash = parseFloat(String((fund as any).cashBalance || "0"));
      const nextBalance = Math.max(0, previousBalance - totalSaleValue);
      const cashAfterLiquidation = previousCash + totalSaleValue;
      await storage.updateFund(fundId, {
        balance: nextBalance.toFixed(2),
        cashBalance: cashAfterLiquidation.toFixed(2),
      } as any);

      const tickerSummary = sales.map(s => s.ticker).join(", ") || "no holdings";
      await storage.createActivity({
        userId,
        fundId,
        type: 'sell',
        title: `Fund liquidated`,
        description: `Sold ${sales.length} ${sales.length === 1 ? 'holding' : 'holdings'} (${tickerSummary}) for $${totalSaleValue.toFixed(2)}. Cash settles in 1 to 2 business days.`,
        amount: totalSaleValue.toFixed(2),
      });

      // Chain the withdrawal if requested.
      let withdrawal: { delivered: boolean; achLive: boolean; amount: string } | null = null;
      if (bankAccount) {
        const withdrawAmount = cashAfterLiquidation;
        if (withdrawAmount > 0) {
          await storage.updateFund(fundId, {
            cashBalance: "0.00",
          } as any);

          const achLive = isCustodianAchEnabled();
          const transferResult = await queueCustodianTransfer({
            type: "liquidation_requested",
            fundId,
            requestedByUserId: userId,
            requestedAt: new Date().toISOString(),
            amount: withdrawAmount.toFixed(2),
            currency: "USD",
            bankAccountId: bankAccount.id,
            bankName: bankAccount.bankName,
            bankLast4: bankAccount.accountLast4,
          });
          const delivered = transferResult.delivered;

          await storage.createActivity({
            userId,
            fundId,
            type: 'withdrawal',
            title: delivered ? 'Cash sent to bank' : 'Withdrawal queued',
            description: delivered
              ? `$${withdrawAmount.toFixed(2)} sent to ${bankAccount.bankName} ending in ${bankAccount.accountLast4}. Expect 1 to 3 business days.`
              : `$${withdrawAmount.toFixed(2)} queued for ${bankAccount.bankName} ending in ${bankAccount.accountLast4}. Our team will complete the transfer manually during early access.`,
            amount: withdrawAmount.toFixed(2),
            metadata: JSON.stringify({
              status: delivered ? 'completed' : 'pending',
              bankName: bankAccount.bankName,
              bankLast4: bankAccount.accountLast4,
              delivered,
              source: 'liquidation',
            }),
          });

          await storage.createTransaction({
            userId,
            type: 'withdrawal',
            amount: withdrawAmount.toFixed(2),
            status: delivered ? 'processing' : 'pending_manual_processing',
            description: `${delivered ? 'Cash sent to' : 'Cash queued for'} ${bankAccount.bankName} ending in ${bankAccount.accountLast4}`,
            fundId,
          });

          withdrawal = { delivered, achLive, amount: withdrawAmount.toFixed(2) };
        }
      }

      await captureFundSnapshot(fundId);

      res.json({
        success: true,
        soldCount: sales.length,
        totalSaleValue: totalSaleValue.toFixed(2),
        cashAfterLiquidation: (withdrawal ? 0 : cashAfterLiquidation).toFixed(2),
        withdrawal,
      });
    } catch (error) {
      console.error('Error liquidating fund:', error);
      const message = error instanceof Error ? error.message : 'Failed to liquidate fund';
      res.status(500).json({ error: message });
    }
  });

