  // ===== SUBSCRIPTION =====
  app.get('/api/subscription', isAuthenticated, async (req: any, res) => {
    try {
      const userId = (req.user as any).id;
      const subscription = await storage.ensureSubscription(userId);
      let starterMemberships: any[] = [];
      try {
        starterMemberships = await storage.getFundMembershipsByUser(userId);
      } catch (membershipErr) {
        if (!isMissingFundMembershipRelationError(membershipErr)) throw membershipErr;
        console.warn("[Subscription] fund_memberships relation missing; returning empty starter memberships.");
      }
      const starterByFund = starterMemberships.reduce<Record<string, any>>((acc, row) => {
        acc[row.fundId] = {
          id: row.id,
          fundId: row.fundId,
          status: row.status,
          billingInterval: row.billingInterval,
          currentPeriodStart: row.currentPeriodStart,
          currentPeriodEnd: row.currentPeriodEnd,
          canceledAt: row.canceledAt,
          stripeSubscriptionId: row.stripeSubscriptionId,
        };
        return acc;
      }, {});
      const activeStarterCount = starterMemberships.filter((row) =>
        hasEntitlementFromStatus(row.status, row.currentPeriodEnd),
      ).length;
      const userFunds = await storage.getFundsByUser(userId);
      const coverageByFundEntries = await Promise.all(
        userFunds.map(async (fund) => [String(fund.id), await getFundCoverageState(userId, fund.id)] as const),
      );
      const coverageByFund = Object.fromEntries(coverageByFundEntries);
      // Per-fund sponsored-subscription metadata (Prong B of pricing-v3
      // conversion, locked 2026-05-23). Drives the "Plus from {Grandma}"
      // attribution badge on Account → Plan tab. The coverage is
      // already handled by coverageByFund above; this is the SOURCE
      // attribution layer the parent sees alongside the standard plan
      // card. Per project_gifter_sponsors_plus_subscription.md.
      const sponsoredByFundEntries = await Promise.all(
        userFunds.map(async (fund) => {
          const sponsored = await getActiveSponsorshipForFund(fund.id);
          return [String(fund.id), sponsored ? {
            tier: sponsored.tier,
            sponsorName: sponsored.sponsorName,
            sponsorEmail: sponsored.sponsorEmail,
            expiresAt: sponsored.expiresAt.toISOString(),
          } : null] as const;
        }),
      );
      const sponsoredByFund = Object.fromEntries(sponsoredByFundEntries);
      const householdPlan =
        (subscription.plan === "legacy" || subscription.plan === "family") &&
        hasEntitlementFromStatus(subscription.status, subscription.currentPeriodEnd);
      const effectivePlan = householdPlan
        ? (subscription.plan === "legacy" ? "legacy" : "family")
        : activeStarterCount > 0
          ? "starter"
          : "free";
      const recommendationState = getRecommendationState(activeStarterCount, Boolean(householdPlan));
      // Plan-fit nudge — the anti-dark-pattern "you're paying for more than you
      // need right now" signal (the inverse of burying the downgrade). When a
      // Family subscriber's active obligations have shrunk to fit a smaller plan —
      // e.g. a second child's fund handed off at majority, leaving exactly one
      // minor fund — surface an honest downgrade offer. READ-ONLY here; the action
      // reuses the proven cancel-at-period-end flow (Family rides out the period
      // already paid for, then the one remaining fund moves to Kiddo+). Gated to
      // the unambiguously-safe case: Family active, not already canceling, no Plus
      // already in play, and exactly 0 or 1 minor fund. A handed-off fund leaves
      // getFundsByUser (ownership moves to the now-adult), and transferredAt-null
      // is the belt-and-suspenders check. See SUBSCRIPTION_DOWNGRADE_SPEC.md.
      let planFit:
        | { kind: "downgrade_to_plus" | "no_plan_needed"; activeFundCount: number; fund: { id: string; name: string; childName: string | null } | null; renewalDate: string | null }
        | null = null;
      if (householdPlan && subscription.plan === "family" && subscription.status !== "canceled" && activeStarterCount === 0) {
        const activeMinorFunds = userFunds.filter((f: any) => !f.transferredAt);
        const renewalDate = subscription.currentPeriodEnd ? new Date(subscription.currentPeriodEnd).toISOString() : null;
        if (activeMinorFunds.length === 1) {
          const f: any = activeMinorFunds[0];
          planFit = { kind: "downgrade_to_plus", activeFundCount: 1, fund: { id: String(f.id), name: f.name, childName: f.recipientFirstName ?? null }, renewalDate };
        } else if (activeMinorFunds.length === 0) {
          planFit = { kind: "no_plan_needed", activeFundCount: 0, fund: null, renewalDate };
        }
      }
      res.json({
        ...subscription,
        effectivePlan,
        recommendationState,
        planFit,
        starterFundCount: activeStarterCount,
        starterMemberships,
        starterByFund,
        coverageByFund,
        sponsoredByFund,
        familyAnnualOptions: [...KORA_FAMILY_YEARLY_OPTIONS],
        activeFamilyYearlyPrice: KORA_DEFAULT_FAMILY_YEARLY,
        activeLegacyYearlyPrice: KIDDO_LEGACY_YEARLY,
        legacyIncludedOccasionCredits: KIDDO_LEGACY_INCLUDED_OCCASION_CREDITS,
      });
    } catch (error) {
      console.error('Error fetching subscription:', error);
      res.status(500).json({ error: 'Failed to fetch subscription' });
    }
  });

